WITH payload AS (SELECT $archive_payload$[{"id":"d60522c9-4bad-58a3-bf8a-214d0137a5d5","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة بيت املال -ولي يطالب بيت املال بتسليم مبلغ والده لعالجه -رأي قسم اخلبراء -التقرير الطبي -شهادة الشاهدين املعدلن -إلزام بيت املال برفع يده عن املبلغ وتسليمه للمدعي مع تقدمي بيان بأوجه الصرف .","document_number":"3453084","case_number":"33674845","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/2","year":"1434","subject":"مطالبة بيت املال -ولي يطالب بيت املال بتسليم مبلغ والده لعالجه -رأي قسم اخلبراء -التقرير الطبي -شهادة الشاهدين املعدلن -إلزام بيت املال برفع يده عن املبلغ وتسليمه للمدعي مع تقدمي بيان بأوجه الصرف .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫تاريخه‪1434/3/2 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3453084 :‬‬\n                         ‫َر ْق ُم الدعوى‪33674845 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34204336‬تاريخه‪1434/5/4 :‬هـ‬\n\n\n      ‫مطالبــة بيــت املــال‪ -‬ولــي يطالــب بيــت املــال بتســليم مبلــغ والــده‬\n      ‫لعالجــه‪ -‬رأي قســم اخلبــراء‪ -‬التقريــر الطبــي‪ -‬شــهادة الشــاهدين‬\n      ‫املعدلــن‪ -‬إلــزام بيــت املــال برفــع يــده عــن املبلــغ وتســليمه للمدعــي مــع‬\n                                                    ‫تقــدمي بيــان بأوجــه الصــرف ‪.‬‬\n\n\n\n\n                        ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n      ‫أقــام ولــي دعــوى علــى بيــت املــال يطالبــه برفــع يــده عــن مبلــغ مــودع يف‬\n      ‫ا وذلــك للقيــام بعالجــه‪ ،‬صــادق‬     ‫بيــت املــال يخــص والــده القاصــر عق ـ ً‬\n      ‫مديــر بيــت املــال علــى وجــود املبلــغ يف بيــت املــال‪ ،‬اطلعــت احملكمــة‬\n      ‫علــى صــك الواليــة كمــا جــرى الكتابــة لقســم اخلبــراء بأخــذ الــرأي‬\n      ‫فيمــا يطالــب بــه املدعــى فقــرروا أنهــم يــرون صــرف املبلــغ للعــاج‬\n      ‫علــى ان يحضــر املدعــى بيانــا موثقــا بصرفــه‪ ،‬كمــا جــرى اطــاع‬\n      ‫احملكمــة علــى التقريــر الطبــي املثبــت ملــرض والــد املدعــي‪ ،‬كمــا‬\n      ‫طلبــت احملكمــة البينــة علــى أن والــده مريــض ويحتــاج للعــاج فأحضــر‬\n      ‫املدعــى شــاهدين شــهدا مبــرض والــده وحاجتــه للعــاج وجــرى تعديــل‬\n      ‫الشــهود وبنــاء علــى إقــرار مديــر بيــت املــال بوجــود املبلــغ وبنــاء علــى‬\n\n‫‪135‬‬\n\f‫التقريــر الطبــي ورأي اخلبــراء وشــهادة الشــاهدين‪ ،‬ثبــت لــدى احملكمــة‬\n‫أن والــد املدعــي مريــض وبحاجــة للعــاج لــذا ألزمــت احملكمــة برفــع‬\n‫يــد بيــت املــال عــن املبلــغ الــذي للقاصــر وتســليمه للولــي املدعــى ليصرفــه‬\n‫علــى عالجــه وأن يقــدم بيانــا تفصيليــا بجميــع مــا يصرفــه‪ ،‬لــم يقتنــع‬\n                                           ‫املدعــى عليــه‪ ،‬صــدق احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫وتاريــخ ‪1433/11/24‬ه ـ املقيــدة باحملكمة يف ‪1433/11/24‬هـ حضر‬\n‫‪ ..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي ‪ ..........‬الولــي علــى‬\n‫والــده مبوجــب صــك الواليــة يف ‪ 1427/5/24‬ه ـ الصــادر مــن محكمــة‬\n‫محافظــة ‪ ..........‬وادعــى علــى مديــر بيــت املــال قائــا بأنــه يوجــد لوالــدي‬\n‫مبلــغ مائــة وخمســة وثمانــن الــف ريــال لــدى ادارة بيــت املــال وأن والــدي‬\n‫بحاجــة إلــى عالجــه يف املستشــفيات داخــل اململكــة وقــد يحتــاج األمــر‬\n‫إلــى عالجــه خــارج اململكــة لــذا أطلــب احلكــم علــى مديــر بيــت املــال‬\n‫بدفــع املبلــغ املذكــور لــي ليتســنى لــي عــاج والــدي منــه هكــذا ادعــي‬\n‫وباالطــاع علــى شــرح مديــر بيــت املــال علــى الدعــوى املقدمــة مــن‬\n‫املدعــي املتضمــن انــه يوجــد لــدى بيــت املــال مبلــغ مائــة وخمســة وثمانــن‬\n‫الــف ريــال لصالــح ‪ 0‬ثــم جــرى االطــاع علــى صــك الواليــة الصــادر مــن‬\n‫محكمــة محافظــة خيبــر يف ‪ 1427/5/24‬ه ـ املتضمــن ان يعانــي مــن‬\n‫الشــيخوخة وضعــف بيــده وال يســتجيب لألســئلة وعــدم القــدرة علــى‬\n‫املشــي بســبب جلطــات ســابقه يف املــخ ويحتــاج الــى مــن يرعــى شــئونه‬\n\n                                                                                       ‫‪136‬‬\n\f      ‫ورعايتــه واقــام احلاكــم الشــرعي ابنــه وليــا عليــه يرعــى أمــوره و يحافــظ‬\n      ‫علــى مصاحلــه ولــه احلــق يف البيــع والشــراء واالســتالم والتســليم‪ .‬ثــم‬\n      ‫جــرى االطــاع علــى قــرار قســم اخلبــراء باحملكمــة العامــة برقــم يف‬\n      ‫‪1434/1/12‬ه ـ املتضمــن أنهــم يــرون صــرف مبلــغ خمســن الــف ريــال‬\n      ‫مــن املبلــغ املذكــور للمدعــي علــى أن يحضــر بيــان بصرفهــا علــى والــده‬\n      ‫ومــا يحتــاج إليــه ويكــون هــذا البيــان موثقــا مــن الورثــة أو بعضهــم ثــم‬\n      ‫جــرى االطــاع علــى التقريــر الطبــي رقــم ق ت خ يف ‪1434/1/7‬ه ـ‬\n      ‫الصــادر مــن مستشــفى خيبــر العــام املتضمــن يعانــي مــن ارتفــاع ضغــط‬\n      ‫الــدم وشــلل نصفــي أيســر وعــدم القــدرة علــى الــكالم واملشــي نتيجــة‬\n      ‫جلطــة ســابقه‪.‬أ‪.‬هـ ثــم طلبــت مــن املدعــي البينــة علــى أن والــده مريــض‬\n      ‫ويحتــاج الــى عــاج فأحضــر كال مــن ســعودي ســعودي وشــهد كل‬\n      ‫واحــد منهمــا مبفــرده قائــا اشــهد هلل تعالــى بــأن‪ .......‬مريــض ومصــاب‬\n      ‫بشــلل نصفــي ايســر وانــه بحاجــه للعــاج هكذا أشــهد ثم جــرت تزكية‬\n      ‫الشــاهدين وفــق األصــول الشــرعية مــن قبــل كل مــن ســعودي و ســعودي‬\n      ‫وشــهد كل واحــد منهمــا قائــا اشــهد هلل تعالــى بــان املذكوريــن أهــل‬\n      ‫ديانــة وأمانــه وهمــا عــدالن مقبــوال الشــهادة هكــذا اشــهد ‪.‬وبنــاء علــى‬\n      ‫الدعــوى واإلجابــة وعلــى خطــاب مديــر بيــت املــال وبنــاء علــى القــرار‬\n      ‫الطبــي الصــادر مــن مستشــفى خيبــر العــام وعلــى قــرار قســم اخلبــراء‬\n      ‫باحملكمــة وبنــاء علــى شــهادة الشــاهدين املعدلــن التعديــل الشــرعي‬\n      ‫فقــد ثبــت لــدي مريــض وأنــه بحاجــه الــى العــاج لــذا فقــد الزمــت مديــر‬\n      ‫بيــت املــال باحملكمــة العامــة باملدينــة برفــع يــده عــن املبلــغ الــذي ‪.....‬‬\n      ‫املذكــور املؤمــن لديــه ومقــداره مائــة وخمســة وثمانــون الــف ريــال‬\n      ‫وتســليمه للولــي عليــه ابنــه ‪ .....‬ليصرفــه علــى عــاج والــده ســواء داخــل‬\n\n\n‫‪137‬‬\n\f‫اململكــة أو خارجهــا وأفهمــت بــأن عليــه أن يقــدم بيانــا تفصيليــا بجميــع‬\n‫مــا يصرفــه علــى والــده وبــه حكمــت وأفهمــت مديــر بيــت املــال ذلــك‬\n‫فقــرر عــدم املعارضــة وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة‬\n‫لتدقيقــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                     ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/2‬هــ‪.‬‬\n‫مت رفــع صــك احلكــم حملكمة االســتئناف عــاد مصدقا بقرار محكمة‬\n‫االســتئناف رقــم ‪ 34204336‬يف ‪1434/5/4‬ه ـ وهــذا نصــه فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف االطــاع علــى‬\n‫الصــك الصــادر مــن فضيلــة الشــيخ القاضــي باحملكمــة العامــة برقــم‬\n‫يف ‪1434/3/2‬ه ـ املتضمــن دعــوى ضــد مديــر بيــت املــال يف مبلــغ مالــي‬\n‫وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــي احلكــم ‪ .‬قاضــي‬\n‫اســتئناف‪ ..........‬قاضــي اســتئناف‪ ..........‬رئيــس الدائــرة ‪ ...........‬وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                             ‫يف ‪1434/5/19‬هــ‪.‬‬\n‫ـاء علــى خطــاب مديــر بيــت املال باحملكمة العامــة ر يف ‪1434/6/6‬هـ‬           ‫بنـ ً‬\n‫املتضمــن انــه مت تســليم مبلــغ مائــه وخمســة وثمانــن ألف ريــال احملكوم‬\n‫بهــا مبوجــب الصــك رقــم يف ‪ 1434/3/2‬ه ـ وذلــك مبوجــب الشــيك رقــم‬\n‫يف ‪ 1434/6/6‬ه ـ وســجل بتقاريــر االوقــاف والقصــر جلــد ‪ 7‬صحيفــة‪4‬‬\n‫وطلبــه التهميــش علــى الصــك والســجل وللمعلوميــة جــرى اثبــات ذلــك‪....‬‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم ‪ .‬حــرر يف ‪1434/6/10‬هــ‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n\n\n                                                                                        ‫‪138‬‬\n\f      ‫جــرى منــا نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف‬\n      ‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة‬\n      ‫مكــة املكرمــة االطــاع علــى الصــك الصــادر من فضيلــة الشــيخ‪..........‬‬\n      ‫القاضــي باحملكمــة وتاريــخ ‪1434/3/2‬ه ـ املتضمــن دعــوى‪..........‬‬\n      ‫ضــد‪ ..........‬مديــر بيــت املــال يف مبلــغ مالــي وبدراســة الصــك وصــورة‬\n      ‫ضبطــه تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                                         ‫نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪139‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":135,"source_page_end":139,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6b371cb4b7c55c3aed4258890066c2ec5b38b0cd10a24e18f0fb86f1fe3dcc40","normalized_text_hash":"8e6b232c0d33768c5d3469b9eb4e3d29bc5689de3aa62c3d9a0cad7df0627419","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p135-3453084"},{"id":"95097cec-a594-5dd9-ba7c-337b68259f65","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة بيت املال -مطالبة ولي باستالم مبلغ مودع ببيت املال لصالح قاصر لإلنفاق عليه وتنميته -مصادقة بيت املال على الدعوى واالستعداد لتسليم املبلغ حال صدور حكم بذلك -رأي قسم اخلبراء -إلزام بيت املال بتسليم املبلغ للمدعي .","document_number":"34194906","case_number":"34120483","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة و","circuit":"الدائرة الثانية لألحوال","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/22","year":"1434","subject":"مطالبة بيت املال -مطالبة ولي باستالم مبلغ مودع ببيت املال لصالح قاصر لإلنفاق عليه وتنميته -مصادقة بيت املال على الدعوى واالستعداد لتسليم املبلغ حال صدور حكم بذلك -رأي قسم اخلبراء -إلزام بيت املال بتسليم املبلغ للمدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/22 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34194906 :‬‬\n                   ‫َر ْق ُم الدعوى‪34120483 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34307547‬تاريخه‪1434/8/28 :‬هـ‬\n\n\n‫مطالبــة بيــت املــال‪ -‬مطالبــة ولــي باســتالم مبلــغ مــودع ببيــت املــال‬\n‫لصالــح قاصــر لإلنفــاق عليــه وتنميتــه‪ -‬مصادقــة بيــت املــال علــى‬\n‫الدعــوى واالســتعداد لتســليم املبلــغ حــال صــدور حكــم بذلــك‪ -‬رأي‬\n            ‫قســم اخلبــراء‪ -‬إلــزام بيــت املــال بتســليم املبلــغ للمدعــي ‪.‬‬\n\n\n\n‫‪ -1‬املــادة رقــم ‪ 179‬مــن نظــام املرافعــات والفقــرة ب مــن الالئحــة‬\n ‫التنفيذيــة واملــادة ‪ 187‬مــن نفــس النظــام ولوائحهــا التنفيذيــة‬\n                            ‫‪ -2‬املادة ‪ 195‬من نظام اإلجراءات اجلزائية‬\n                                ‫‪ -3‬ما ذكره القاضي يف أسباب احلكم‬\n\n\n\n\n‫أقــام ولــي دعــوى علــى بيــت املــال يطالبــه بتســليم مبلــغ خــاص بقاصــر‬\n‫اودع يف بيــت املــال‪ ،‬أقــر املدعــى عليــه مبــا جــاء يف دعــوى املدعــى وقــرر‬\n‫أنــه ال مانــع لديــه مــن تســليم املدعــى املبلــغ إذا صــدر حكــم يلــزم بيــت‬\n‫املــال بذلــك‪ ،‬اطلعــت احملكمــة علــى صــك حصــر الورثــة وعلــى صــك‬\n‫الواليــة وعلــى الصــك الــذي مبوجبــه أودع مــال القاصــر يف بيــت املــال‪،‬‬\n‫ثــم ســألت احملكمــة املدعــي عــن ســبب طلبــه ملــال القاصــر فذكــر أنــه‬\n‫يريــد تنميــة املــال وصرفــه علــى القاصــر مــن ريعــه فكتبــت احملكمــة‬\n\n                                                                                     ‫‪140‬‬\n\f      ‫لقســم اخلبــراء ألخــذ رأيهــم يف طلــب املدعــي فــرأوا أن تســليم مبلــغ‬\n      ‫القاصــر لوليــه لتنميتــه أفضــل مــن بقائــه يف بيــت املــال‪ ،‬وبنــاء علــى قــرار‬\n      ‫قســم اخلبــراء وبنــاء علــى املــادة ‪ 179‬والفقــرة ب مــن الالئحــة التنفيذيــة‬\n      ‫لــذا حكمــت احملكمــة علــى بيــت املــال بتســليم املبلــغ للولــي وأفهمتــه‬\n      ‫بــأن يقــدم بيانــا تفصيليــا مبــا يصــرف علــى القاصــر‪ ،‬اعتــرض املدعــى‬\n                                                                  ‫عليــه وصــدق احلكــم‪.‬‬\n\n\n\n\n      ‫أمــا‬\n          ‫الســام علــى مــن ال نبـ َّـي بعــده ‪َّ ...‬‬\n                                                    ‫والصــاة و َّ‬    ‫َّ‬  ‫احلمــد هلل وحــده‪،‬‬\n      ‫العامــة يف ‪ ، ..........‬القائــم‬\n                                    ‫َّ‬    ‫ـدي أنــا ‪ ، ..........‬القاضــي باحملكمــة‬\n                                                                                  ‫بعــد‪ :‬فلـ َّ‬\n      ‫الشــيخ‪ ، ..........‬القاضــي باحملكمــة نفســها‪ .‬حضــر‬             ‫بعمــل فضيلــة َّ‬\n      ‫وليا على أخيــه املواطن‪..........‬‬   ‫ـعودي اجلنسـ َّـي ِة بصفتــه ً‬\n                                                                   ‫املواطــن‪ُ ، ..........‬سـ ُّ‬\n      ‫الصادر من هذه احملكمة‬            ‫اجلنسي ِة ‪ .‬مبوجب إعالم «الوالية» َّ‬‫َّ‬       ‫عودي‬\n                                                                                    ‫‪ُ ،‬س ُّ‬\n      ‫ســي ِة‬\n            ‫ـعودي اجلن َّ‬\n                    ‫يف ‪1426/05/27‬هـ‪ .‬وا َّدعى على احلاضر معه‪ُ ،..........‬سـ ِّ‬\n      ‫مبوجــب ‪ ، ..........‬بصفتــه مديــر بيــت املــال يف هــذه احملكمــة‪ .‬قائـ ًـا‬\n      ‫أن قمــت ـ ـ بصفتــي وكيـ ًـا عــن ورثــة املواطــن‪..........‬‬    ‫يف َّدعــواه‪ :‬ســبق َّ‬\n      ‫ـكنية»‪ ،‬الواقعــة يف ‪ ..........‬مببلـ ٍـغ قــدره مليــون‬\n                                                            ‫َّ‬    ‫السـ‬\n                                                                     ‫ـ ـ ببيــع «العمــارة َّ‬\n      ‫الصادر من هذه احملكمة‬         ‫(‪ )1,000,000‬ريالٍ ‪ ،‬و ذلك مبوجب اإلعالم َّ‬\n      ‫يف ‪1431/03/16‬هــ‪ ،‬و قــد َّت إيــداع مبلــغ قــدره تســع ٌة و ســبعون ألــف‬\n      ‫ـال و خمســون (‪ )79,545/50‬هللــة‬           ‫و خمســمائ ٍة وخمس ـ ٍة و أربعــون ريـ ً‬\n      ‫إلــى بيــت مــال هــذه احملكمــة لصالــح القاصــر‪ ، ..........‬و ذلــك مبوجــب‬\n      ‫اخلطــاب يف ‪1431/04/26‬هــ‪ ،‬ومبوجــب إيصــال «اســتالم ال ُّنقــود» رقــم‬\n      ‫(‪ )8/655889‬يف ‪1431/04/26‬هــ‪ ،‬ومبــا أ َّنــي ولـ ٌـي علــى أخــي «‪»....‬‬\n\n‫‪141‬‬\n\f‫أرغـ ُـب يف اســتالم ذلــك املبلــغ املــودع‪ ،‬وقــدره تســع ٌة وســبعون ألــف و‬\n‫ـال و خمســون هللــة (‪)79,545/50‬؛‬                ‫خمســمائ ٍة و خمس ـ ٍة و أربعــون ريـ ً‬\n‫الدعــوى‪،‬‬  ‫املدعــى عليــه ـ ـ مديــر بيــت املــال ـ ـ عــن هــذه َّ‬\n                                                                    ‫لــذا أطلــب ســؤال َّ‬\n‫املدعــى بــه‪ ،‬و قــدره تســع ٌة وســبعون‬      ‫و إلزامــه بتســليمي كامــل املبلــغ َّ‬\n‫ـال وخمســون هللــة (‪)79,545/50‬‬              ‫ألــف وخمســمائ ٍة وخمسـ ٍة وأربعــون ريـ ً‬\n‫املدعــى عليــه ـ ـ مديــر بيــت‬   ‫ـال‪ ،‬هــذه دعــواي‪ .‬و بعــرض ذلــك علــى َّ‬           ‫حـ ً‬\n‫املدعــي أصالـ ًة ووكالـ ًة يف دعــواه ك ُّلــه‬    ‫املــال ـ ـ أجــاب بقولــه‪ :‬مــا ذكــره َّ‬\n‫صحيـ ٌـح جمل ـ ًة و تفصيـ ًـا‪ ،‬فقــد َّت إيــداع مبلـ ٍـغ قــدره تســع ٌة وســبعون‬\n‫ـال و خمســون (‪)79,545/50‬‬              ‫ألــف و خمســمائ ٍة و خمس ـ ٍة و أربعــون ريـ ً‬\n‫هلل ـ ًة إلــى بيــت مــال هــذه احملكمــة لصالــح املواطــن‪ ،..........‬و ذلــك‬\n‫مبوجــب اخلطــاب يف ‪1431/04/26‬هــ‪ ،‬و مبوجــب إيصــال «اســتالم‬\n‫ـدي مــن‬‫ال ُّنقــود» رقــم (‪ )8/655889‬يف ‪1431/04/26‬هــ‪ ،‬و ال مانــع لـ َّ‬\n‫املدعــى بــه ـ ـ املــودع لدينــا ــ‪ ،‬و قــدره تســع ٌة‬\n                                                      ‫املدعــي كامــل املبلــغ َّ‬\n                                                                               ‫تســليم َّ‬\n‫ـال وخمســون هللــة‬      ‫و ســبعون ألــف وخمســمائ ٍة و خمس ـ ٍة و أربعــون ريـ ً‬\n‫(‪ ، )79,545/50‬متــى صــدر حكـ ٌـم ُيلـ ِـز ُم بيــت املــال بذلــك‪ ،‬هكــذا‬\n‫بطياتهــا مــا ذكــره‬           ‫أجــاب‪ .‬فجــرى االطِّ ــاع علــى أوراق املعاملــة‪ُ ،‬‬\n                    ‫فو ِجـ َـد َّ‬\n‫الدعــوى‪ ،‬و تفصيلهــا كمــا يلــي‪/‬‬         ‫املدعــي‪ ،‬و هــي مطابقـ ٌة ملــا ُذكــر يف َّ‬   ‫َّ‬\n‫الصــادر مــن هــذه احملكمــة‬    ‫َّأو ًل‪ :‬إعــام «إثبــات الوفــاة و حصــر الورثــة» َّ‬\n‫املتضمــن‪« :‬وفــاة‪،..........‬‬\n                           ‫ِّ‬         ‫برقــم (‪ )16/116‬يف ‪1412/09/06‬هــ‪ ،‬و‬\n‫بتاريــخ ‪1412/06/25‬هــ‪ ،‬و انحصــار إرثــه يف زوجتــه‪ ..........‬و يف أوالده‬\n‫ثانيــا‪ :‬االطِّ ــاع علــى إعــام‬    ‫كل مــن‪ ..........‬ال وارث لــه ســواهم» ا‪.‬هــ‪ً .‬‬ ‫ٍّ‬\n‫املتضمن‪:‬‬\n   ‫ِّ‬          ‫الصــادر مــن هــذه احملكمــة (يف ‪1421/05/08‬ه ــ‪ ،‬و‬          ‫الواليــة َّ‬\n‫«إقامــة املواطــن‪ ،..........‬و ًّليــا علــى أخيــه القاصــر» ا‪.‬هــ‪ .‬ثال ًثــا‪ :‬القــرار‬\n\n\n                                                                                                ‫‪142‬‬\n\f      ‫العامــة باملدينــة املنـ َّـورة (‪)8‬‬\n                                        ‫َّ‬      ‫الصــادر مــن احملكمــة‬      ‫ـرعي القطعـ ُّـي َّ‬‫الشـ ُّ‬\n                                                                                                      ‫َّ‬\n      ‫واملتضمــن‪« :‬اإلذن ببيــع العمــارة ـ ـ املوصوفــة يف‬      ‫ِّ‬          ‫يف ‪1431/3/16‬هــ‪))،‬‬\n      ‫الدعــوى ــ‪ ،‬مببلـ ٍـغ قــدره مليــون (‪ )1,000,000‬ريــالٍ ‪ ،‬و تســليم نصيــب‬                       ‫َّ‬\n      ‫القاصريــن «‪ »....‬و «‪ »....‬و هــو مبلـ ٌغ قــدره مائــة و تســع ٌة و خمســون ألــف‬\n      ‫رابعــا‪ :‬خطــاب مديــر‬     ‫ـال» ا‪.‬هــ‪ً .‬‬     ‫و واحـ(‪ )1‬ــد و تســعون (‪ )159,091‬ريـ ً‬\n      ‫املتضمــن‪« :‬اســتالم‬‫ِّ‬        ‫بيــت مــال هــذه احملكمــة‪ ،‬يف ‪1434/03/14‬هــ‪ ،‬و‬\n      ‫بيــت مــال هــذه احملكمــة مبل ًغــا قــدره تســع ٌة وســبعون ألــف وخمســمائ ٍة‬\n      ‫ـال وخمســون هللــة (‪ ، )79,545/50‬وذلــك مبوجــب‬                         ‫وخمسـ ٍة وأربعــون ريـ ً‬\n      ‫ـص املواطــن ‪،.............‬‬    ‫اإليصــال يف ‪1431/04/26‬هــ‪ ،‬و هــي مــا يخـ ُّ‬\n      ‫ومــا زال املبلــغ موجــو ًدا ح َّتــى تاريخــه» ا‪.‬هــ‪ .‬فجــرى ســؤال املدعــي عــن‬\n      ‫املدعــى بــه فأجــاب بقولــه‪ :‬لكــي أعمــل علــى‬                   ‫ســبب طلبــه للمبلــغ ـ ـ َّ‬\n      ‫ـدي‪ .‬لــذا فقــد‬  ‫تنميتــه للقاصــر‪ ،‬والصــرف مــن ريعهــا عليــه‪ ،‬هــذا مــا لـ َّ‬\n      ‫جــرى الكتابــة لقســم ا ُخلبــراء بهــذه احملكمــة باخلطــاب (‪ )..........‬يف‬\n      ‫املدعــي مــن تنميــة للمــال‪ ،‬فوردنــا‬       ‫‪1434/03/18‬هــ؛ لتقديــر مــا ذكــره َّ‬\n      ‫ـص‬ ‫اجلــواب منهــم باخلطــاب رقــم (‪ )34/684267‬يف ‪1434/03/24‬ه ـ ونـ ُّ‬\n      ‫ـأن الولــي علــى القاصــر أفــاد يف طلبــه املرفــق‬          ‫احلاجــة منــه‪ « :‬نفيدكــم بـ َّ‬\n      ‫أن بقــاء املبلــغ يف بيــت املــال ليــس فيــه مصلحــة للقاصــر‪ ،‬و أن املصلحــة‬\n      ‫الصــرف‬  ‫تكــون يف إخــراج هــذا املبلــغ‪ ،‬و البيــع والشــراء فيــه وتنميتــه و َّ‬\n      ‫علــى القاصــر مــن ريعــه أفضــل لــه؛ لــذا نــرى ـ ـ والــرأي لفضيلتكــم ـ ــإن‬\n      ‫ـإن إخراجــه أفضــل» ا‪.‬ه ـ القائــم‬             ‫كان األمــر كمــا ذكــر الولــي‪ ،‬فـ َّ‬\n      ‫املدعــي ا َّدعــى‬\n                      ‫أن َّ‬  ‫ـاء علــى مــا تقـ َّـدم؛ و مبــا َّ‬\n                                                               ‫بعمــل رئيــس قســم ا ُخلبــراء‪ .‬فبنـ ً‬\n      ‫املدعــى عليــه ـ ـ مديــر بيــت املــال ـ ـ بدفــع‬    ‫مبــا ا َّدعــى بــه‪ ،‬و طلــب إلـ َّـز َام َّ‬\n      ‫املدعــى بــه‪ ،‬و املــودع لــدى بيــت مــال هــذه احملكمــة‪ ،‬و قــدره‬                   ‫املبلــغ َّ‬\n\n‫‪143‬‬\n\f‫ـال وخمســون‬             ‫تســع ٌة وســبعون ألــف و خمســمائ ٍة وخمس ـ ٍة وأربعــون ريـ ً‬\n‫املدعــى عليــه ـ ـ مديــر بيــت املــال ـ ـ صــادق‬               ‫أن َّ‬‫هللــة (‪)79,545/50‬؛ ومبــا َّ‬\n‫املدعــي كامــل‬           ‫ـتعد بتســليم َّ‬  ‫علــى دعــواه علــى اإلجمــال و ال َّتفصيــل‪ ،‬واسـ َّ‬\n‫املبلــغ املــودع لــدى بيــت مــال هــذه احملكمــة متــى صــدر حكـ ٌـم يقضــي‬\n‫بإلزامــه بذلــك؛ و ملــا رآه قســم اخلبــراء مــن كــون صــرف املــال لتنميتــه‬\n‫نصــت عليــه املــادة (‪ )179‬فقــرة (ب) مــن نظــام املرافعــات‬                            ‫أفضــل‪ ،‬وملــا َّ‬\n‫الصــادر يف مبلـ ٍـغ أودعــه أحــد األشــخاص‬                         ‫أن ا ُحلكــم َّ‬    ‫ـرعية مــن َّ‬\n                                                                                                    ‫الشـ َّ‬       ‫َّ‬\n‫ـخص آخـ ٍـر أو ورثتــه‪ ،‬فليــس علــى احملكمة متييزه ما لم يكن‬                                ‫لصالــح شـ ٍ‬\n‫أن اجلهــة املودع ـ ِة للمبلـ ِـغ‬        ‫للمــو ِّدع‪ ،‬أو مــن مي ِّثلــه معارض ـ ٌة يف ذلــك؛ و مبــا َّ‬\n‫حســبما يظهــر مــن‬             ‫للمدعــي ـ ـ ْ‬  ‫املدعــى بــه ليــس لهــا معارضـ ٌة يف تســليمه َّ‬          ‫َّ‬\n‫املدعــى عليــه‬    ‫أوراق املعاملــة ــ؛ و جلميــع مــا َسـل ََف‪ ،‬فقــد حكمـ ُـت بإلــزام َّ‬\n‫املدعــى‬   ‫للمدعــي كامــل املبلــغ َّ‬             ‫‪-‬بيــت مــال هــذه احملكمــة‪ -‬بــأن يدفــع َّ‬\n‫ـال‬   ‫بــه‪ ،‬وقــدره تســع ٌة وســبعون ألــف وخمســمائ ٍة وخمس ـ ٍة وأربعــون ريـ ً‬\n‫ـرف‬ ‫املدعــي َّأل يتصـ َّ‬         ‫ـال‪ ،‬وأفهمـ ُـت َّ‬       ‫وخمســون هللــة (‪ )79,545/50‬حـ ً‬\n‫الصــادر والــوارد‪ ،‬وأن يقـ ِّـدم‬             ‫بشــي ٍء مــن مــال القاصــر َّإل بقيــده وكتابــة َّ‬\n‫ـنويا مبــا قــام بــه جتــاه أمــوال وحقــوق القاصر‪-‬املذكــور‪،-‬‬                                ‫بيا ًنــا سـ ًّ‬\n‫وأوصيتــه بتقــوى اهلل ‪-‬جــلَّ جاللــه‪ -‬يف واليتــه‪ ،‬وبإعــان ا ُحلكــم علــى‬\n‫املدعــى عليــه‪ ،‬و طلــب رفــع ا ُحلكــم‬                ‫املدعــي‪ ،‬ولــم يقنــع َّ‬ ‫املتداعيــن‪ ،‬قنــع َّ‬\n‫اعتراضيــة‪ ،‬ف ُأجيــب‬‫َّ‬               ‫ـتعد بتقــدمي الئحـ ٍة‬  ‫إلــى محكمــة االســتئناف‪ ،‬واسـ َّ‬\n‫ـأن لــه اســتالم نســخ ٍة مــن إعــام ا ُحلكــم يف هــذا اليــوم‬                   ‫لطلبــه‪ ،‬و ُأفهــم بـ َّ‬\n‫يومــا مــن اليــوم‬     ‫الســبت ‪1434/4/20‬هــ‪ ،‬وأ َّنــه متــى مضــى ثالثــون (‪ً )30‬‬                            ‫َّ‬\n‫حقــه‬   ‫ـإن َّ‬‫االعتراضيــة‪ ،‬فـ َّ‬\n                             ‫َّ‬                   ‫الــذي يلــي هــذا ال َّتاريــخ‪ ،‬ولــم ُيس ـلِّم الئحتــه‬\n‫وأن إعــام ا ُحلكــم‪ ،‬وصــورة ضبطــه‬                            ‫يف طلــب االســتئناف يســقط‪َّ ،‬‬\n\n                                                                                                                       ‫‪144‬‬\n\f      ‫ـفوعا باملعاملــة ســوف ُيرفــع إلــى محكمــة االســتئناف ـ ـ بــإذن اهلل ـ ـ‬                                ‫مشـ ً‬\n      ‫وحـ ِّـر َر‬ ‫اجلزائيــة‪ ،‬ففهــم ذلــك‪ُ ،‬‬           ‫َّ‬           ‫عمـ ًـا باملــا َّدة (‪ )195‬مــن نظــام اإلجــراءات‬\n      ‫نبينــا‬ ‫يف ‪1434/04/20‬هــ‪ ،‬و بــاهلل ال َّتوفيــق‪ ،‬و ص َّلــى اهلل و س ـلَّم علــى ِّ‬\n                                                                      ‫محمــدٍ ‪ ،‬و علــى آلــه و صحبــه أجمعــن‪.‬‬            ‫َّ‬\n      ‫أمــا بعــد‪:‬‬          ‫والســام علــى مــن ال نبـ َّـي بعــده َّ‬        ‫والصــاة َّ‬   ‫احلمــد هلل وحــده‪َّ ،‬‬\n      ‫ُكرمــة‬   ‫مبكــة امل َّ‬         ‫َّ‬           ‫فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫باخلطــاب يف ‪1434/6/27‬هــ‪ ،‬وقُ ِّيــدت بأســاس احملكمــة يف‬\n      ‫القضيــة‪..........‬‬        ‫َّ‬          ‫الصــادر م ِّنــي‬     ‫ـ‪،‬مرفقــا بهــا اإلعــام َّ‬\n                                                                                         ‫ً‬          ‫‪1434/07/03‬ه‬\n      ‫الدائــرة‬        ‫الصــادر مــن َّ‬        ‫يف ‪1434/04/22‬هــ‪ ،‬واملالحــظ عليــه بالقــرار َّ‬\n      ‫القصــار‪،‬‬          ‫َّ‬        ‫ـخصية‪ ،‬واألوقــاف‪ ،‬و الوصايــا‪ ،‬و‬               ‫َّ‬        ‫الشـ‬\n                                                                                              ‫الثَّانيــة لألحــوال َّ‬\n      ‫ـص احلاجــة منــه‬                  ‫واملتضمــن مــا نـ ُّ‬ ‫ِّ‬         ‫وبيــوت املــال‪ ،‬يف ‪1434/6/21‬ه‪،،‬‬\n      ‫مــا يلــي «بدراســة اإلعــام‪ ،‬وصــورة ضبطــه‪ ،‬تقـ َّـرر إعادتهــا لفضيلــة‬\n      ‫املدعــى عليــه ـ ـ منــدوب بيــت املــال ـ ـ قـ َّـرر عــدم‬                    ‫حاكمهــا؛ ملالحظــة أن َّ‬\n      ‫ـتعد بتقــدمي الئحــة اعتراضيــة‪ ،‬ولــم جندهــا مرفقـ ًة‪ ،‬ولــم‬                             ‫القناعــة‪ ،‬واسـ َّ‬\n      ‫عمــا ذكــر‬             ‫ـببا لعــدم إرفاقهــا‪ ،‬و ال بــد مــن ذلــك» ا‪.‬هــ‪ .‬و ُيجــاب َّ‬                 ‫يوضــح سـ ً‬\n      ‫املدعــى‬       ‫أصحــاب الفضيلــة بأ َّنــه جــرى فتــح اجللســة‪ ،‬و فيهــا حضــر َّ‬\n      ‫املدعــى‬     ‫عليــه مديــر بيــت املــال بهــذه احملكمــة ‪ ،..........‬فجــرى ســؤال َّ‬\n      ‫االعتراضيــة؟؛ فأجــاب بقولــه‪:‬‬               ‫َّ‬                ‫عليــه عــن ســبب عــدم إرفاقــه لالئحتــه‬\n      ‫رت االعتــراض علــى ا ُحلكــم‪ ،‬و لك َّننــي لــم أرغــب بتقــدمي‬                                  ‫أ َّننــي قــد قـ َّـر ُ‬\n      ‫ـهوا مــن قبــل الكاتــب‪،‬‬                        ‫اعتراضي ـةٍ‪ ،‬و قــد جــرى تدويــن ذلــك سـ ً‬  ‫َّ‬               ‫الئح ـ ٍة‬\n      ‫تذييلــه مبــا ُذكــر بعاليــه‪،‬‬                      ‫هكــذا أجــاب‪ .‬و قـ َّـررت رفــع اإلعــام ـ ـ بعــد ِّ‬\n      ‫ـفوعا بكامــل أوراق املعاملــة‬                          ‫وإحلاقــه بســجلِّه ـ ـ مــع صــورة ضبطــه‪ ،‬مشـ ً‬\n      ‫إلــى محكمــة االســتئناف؛ لتدقيقــه‪ ،‬و عمـ ًـا باملــا َّدة (‪ )187‬مــن نظــام‬\n\n\n‫‪145‬‬\n\f‫نفيذيــة‪ ،‬و ُحـ ِّـرر يف ‪1434/8/6‬ه ـ‬                  ‫َّ‬         ‫ـرعية‪ ،‬و لوائحــه ال َّت‬         ‫الشـ َّ‬‫املرافعــات َّ‬\n‫محمــدٍ ‪ ،‬وعلــى آلــه‬             ‫َّ‬   ‫نبينــا‬\n                                            ‫و بــاهلل ال َّتوفيــق‪ ،‬وص َّلــى اهلل و س ـلَّم علــى ِّ‬\n                                                                                                    ‫وصحبــه أجمعــن‪.‬‬\n‫أمــا بعــد‪:‬‬   ‫الســام علــى مــن ال نبـ َّـي بعــده‪َّ ،‬‬               ‫الصــاة و َّ‬     ‫احلمــد هلل وحــده‪ ،‬و َّ‬\n‫ُكرمة باخلطاب‬              ‫مبكــة امل َّ‬ ‫فقــد عــادت املعاملــة من محكمة االســتئناف َّ‬\n‫رقــم (‪ )34/632434‬يف ‪1434/9/6‬هــ‪ ،‬و قُ ِّيــدت بأســاس احملكمــة‬\n‫مرفقــا بهــا اإلعــام‬                ‫ً‬       ‫برقــم (‪ )34/632434‬يف ‪1434/09/15‬هــ‪،‬‬\n‫الصــادر مــن املكتــب العشــرين برقــم (‪ )34194906‬يف ‪1434/4/22‬ه‪،‬‬                                                   ‫َّ‬\n‫ـخصية‪،‬‬    ‫َّ‬          ‫الشـ‬\n                        ‫الدائــرة الثَّانيــة لألحــوال َّ‬           ‫الصــادر مــن َّ‬       ‫واملصـ َّـدق بالقــرار َّ‬\n‫والقصــار‪ ،‬وبيــوت املــال‪ ،‬برقــم (‪)34307547‬‬                                    ‫َّ‬     ‫واألوقــاف‪ ،‬والوصايــا‪،‬‬\n‫ـص احلاجــة منــه مــا يلــي «بدراســة‬                   ‫املتضمــن مــا نـ ُّ‬ ‫ِّ‬        ‫يف ‪1434/08/28‬هــ‪ ،‬و‬\n‫اإلعــام‪ ،‬و صــورة ضبطــه‪ ،‬تقـ َّـرر املوافقــة علــى ا ُحلكــم بعــد اإلجــراء‬\n‫األخيــر» ا‪.‬هــ‪ .‬و ُحـ ِّـرر يف ‪1434/09/23‬هــ‪ ،‬و بــاهلل ال َّتوفيــق‪ ،‬و ص َّلــى‬\n                       ‫محمــدٍ ‪ ،‬و علــى آلــه وصحبــه أجمعــن‪.‬‬                     ‫نبينــا َّ‬ ‫اهلل و سـَّـلم علــى ِّ‬\n‫أمــا بعــد‪:‬‬ ‫الســام علــى مــن ال نبـ َّـي بعــده ‪َّ ،‬‬                  ‫الصــاة و َّ‬     ‫احلمــد هلل وحــده‪ ،‬و َّ‬\n‫ـاب الــوارد إلينــا مــن بيــت املــال يف هــذه احملكمــة‪،‬‬                                      ‫ـاء علــى اخلطـ ُ‬\n                                                                                                                 ‫فبنـ ً‬\n‫مت تســليم‬          ‫ـص احلاجــة منــه‪َّ « :‬‬       ‫املتضمــن مــا نـ ُّ‬     ‫ِّ‬          ‫يف ‪1434/10/22‬هــ‪ ،‬و‬\n‫ألفــا وخمســمائ ٍة‬              ‫املدعــي املواطــن‪ ،..........‬مبل ًغــا قــدره تســع ٌة وســبعون ً‬                    ‫َّ‬\n‫ـال وخمســون هللــة (‪ ،)79,545/50‬مبوجــب‬                                               ‫وخمس ـ ٌة وأربعــون ريـ ً‬\n‫الشــيك رقــم ‪ ..........‬يف ‪1434/09/24‬هــ‪ ،‬وسـ ِّـجل بتقاريــر األوقــاف‬                                                  ‫ِّ‬\n‫والقصــر واملعتوهــن‪ ،‬جلــد (‪ ،)7‬صحيفــة (‪ »)18‬ا‪.‬هــ‪ .‬وعمـ ًـا باملــا َّدة‬\n‫نفيذيــة ُحـ ِّـر َر‬\n                 ‫َّ‬          ‫ـرعية ولوائحــه ال َّت‬ ‫الشـ َّ‬   ‫(‪ )12/202‬مــن نظــام املرافعــات َّ‬\n‫نبينــا‬ ‫يف ‪1434/10/29‬هــ‪ ،‬و بــاهلل ال َّتوفيــق‪ ،‬و ص َّلــى اهلل وس ـلَّم علــى ِّ‬\n\n                                                                                                                               ‫‪146‬‬\n\f                                          ‫محمــدٍ ‪ ،‬وعلــى آلــه وصحبــه أجمعــن‪.‬‬ ‫َّ‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ :‬فقــد جــرى منــا‬\n      ‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n      ‫والقصــار وبيــوت املــال مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‬\n      ‫االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ‪ ..........‬القاضــي‬\n      ‫باحملكمــة العامــة وتاريــخ ‪1434/4/22‬ه ـ املتضمــن دعــوى ضــد‪..........‬‬\n      ‫بيــت املــال ‪ ،‬وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى‬\n      ‫احلكــم بعــد االجــراء االخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                         ‫وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪147‬‬\n\f148\n\f149\n\f150\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":140,"source_page_end":150,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"34ab67f4f436c4e96d83f6ebab31467953d2e4ec2305cd42d874b4716c2957b5","normalized_text_hash":"85a60d3e58541b2df152222db6cc8944b22a1d0b4ef24ea943b3c9f13bed56f0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p140-34194906"},{"id":"b43979f5-6772-5d1b-82d2-27e702d2aec2","document_type":"judgment","category":"judicial","subcategory":"general","title":"زنا -زنا غير محصن -حد زنا غير احملصن -إقرار بالزنا وانتهاك حرمة املنزل -تعزير بالسجن واجللد والتوصية باإلبعاد حديث عبادة يف صحيح مسلم أن النبي صلى اهلل عليه وسلم قال ال البكر بالبكر جلد (خذوا عني خذوا عني قد جعل اهلل لهن سبي مائة وتغريب عام والثيب بالثيب جلد مائة والرجم).","document_number":"345654","case_number":"347834","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف بالدمام بكتاب فضيلة رئيسها","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/07","year":"1434","subject":"زنا -زنا غير محصن -حد زنا غير احملصن -إقرار بالزنا وانتهاك حرمة املنزل -تعزير بالسجن واجللد والتوصية باإلبعاد حديث عبادة يف صحيح مسلم أن النبي صلى اهلل عليه وسلم قال ال البكر بالبكر جلد (خذوا عني خذوا عني قد جعل اهلل لهن سبي مائة وتغريب عام والثيب بالثيب جلد مائة والرجم).","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 345654 :‬تاريخه‪1434/01/07:‬هـ‬\n                          ‫رقم الدعوى‪347834 :‬‬\n            ‫قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3427297‬تاريخه‪1434/2/2 :‬هـ‬\n\n\n      ‫زنــا ‪ -‬زنــا غيــر محصــن ‪ -‬حــد زنــا غيــر احملصــن‪ -‬إقــرار بالزنــا وانتهــاك‬\n                    ‫حرمــة املنــزل‪ -‬تعزيــر بالســجن واجللــد والتوصيــة باإلبعــاد‬\n\n\n\n\n      ‫حديــث عبــادة يف صحيــح مســلم أن النبــي صلــى اهلل عليــه وســلم قــال‬\n      ‫ال البكــر بالبكــر جلــد‬\n                             ‫(خــذوا عنــي خــذوا عنــي قــد جعــل اهلل لهــن ســبي ً‬\n                      ‫مائــة وتغريــب عــام والثيــب بالثيــب جلــد مائــة والرجــم)‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــى العــام ضــد املدعــى عليــه بانتهاكــه حرمــة املنــزل وفعــل‬\n      ‫ـاغ تقــدم بــه أحــد املواطنــن إلــى اجلهــات‬\n                                                  ‫فاحشــة الزنــا باخلادمــة إثــر بـ ٍ‬\n      ‫املختصــة مبلغ ـ ًا عــن دخــول املدعــى عليــه ملنزلــه وفعــل فاحشــة الزنــا‬\n      ‫بخادمتــه وطلــب املدعــي العــام احلكــم عليــه بحــد الزنــا غيــر احملصــن‬\n      ‫وبعقوبــة تعزيريــة لقــاء انتهاكــه حلرمــة املنــزل‪ ،‬بعــرض دعــوى املدعــي‬\n      ‫العــام علــى املدعــى عليــه صادق عليها‪ ،‬وبســؤاله عن اإليــاج‪ ،‬أجاب أنه‬\n      ‫أولــج مقدمــة ذكــره يف دبرهــا مــن اخللــف وغيبــه فيــه‪ ،‬فجــرى تكــرار‬\n      ‫الســؤال عليــه أربع ـ ًا وأجــاب مبــا أجــاب بــه‪ ،‬وبســؤاله عــن إحصانــه‬\n      ‫أجــاب بأنــه غيــر محصــن وإلقــرار املدعــى عليــه بفعلــه الفاحشــة يف‬\n      ‫اخلادمــة بإيالجــه حلشــفة آلتــه يف دبرهــا وإلقــراره أربــع مــرات وإلقــراره‬\n\n‫‪151‬‬\n\f‫بانتهــاك حرمــة املنــزل ولتحقــق شــروط وجــوب حــد الزنــا وهــي أن يطــأ‬\n‫ا كان أو دبــر ًا وأقــل مــا يطــأ بــه أن يغيــب حشــفته يف فــرج‬ ‫يف الفــرج قبـ ً‬\n‫وأن تنتفــي الشــبهة وثبــوت الزنــا بشــهادة أو بإقــرار أربع ـ ًا يف مجلــس أو‬\n‫مجالــس مــن بالــغ عاقــل يصــرح بذكــر حقيقــة الــوطء‪ ،‬بنــاء علــى مــا‬\n‫تقــدم حكمــت احملكمــة بإقامــة حــد زنــا غيــر احملصــن علــى املدعــى‬\n‫عليــه وذلــك بجلــده مائــة جلــدة دفعــة واحــدة علن ـ ًا وتغريبــه مــدة عــام‬\n‫وتعزيــره بســجنه مــدة ثمانيــة أشــهر وجلــده تســعني جلــدة النتهاكــه‬\n‫حرمــة املنــزل مــع التوصيــة بإبعــاده مــن البــاد بعــد تنفيــذ العقوبــة‬\n‫وبعــرض احلكــم علــى الطرفــن اعتــرض عليــه املدعــي العــام وطلــب‬\n‫اســتئنافه دون تقــدمي الئحــة اعتراضيــة وقنــع بــه املدعــى عليــه وبعــد رفــع‬\n                        ‫احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــدهلل وحــده وبعــد لــدي أنــا ‪...‬القاضــي باحملكمــة اجلزائيــة بالقطيف‬\n‫بنــاء علــى املعاملــة احملالــة إلــي مــن فضيلــة الرئيــس برقــم ‪ 347834‬يف‬\n‫‪1434/1/5‬ه ـ والــواردة بكتــاب رئيــس دائــرة التحقيــق واالدعــاء العــام‬\n‫مبحافظــة القطيــف بكتابــه ذي الرقــم ه ق‪ 58/2/4‬يف ‪1434/1/5‬ه ـ‬\n‫حضــر املدعــي العــام ‪ ..............‬مبوجــب كتــاب التكليــف رقــم ه ـ ق‬\n‫‪ 2156/2/4‬يف ‪1431/9/15‬ه ـ وادعــى علــى احلاضــر معــه ‪...‬مينــي‬\n‫اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ )......‬حيــث أنــه بتاريــخ‬\n‫‪1433/11/25‬ه ـ تقــدم ‪... /‬إلــى مركــز شــرطة صفــوى مبلغ ـ ًا عــن‬\n‫دخــول املدعــى عليــه ملنزلــه وفعــل فاحشــة الزنــا باخلادمــة‪( ... /‬مت فــرز‬\n‫أوراق مســتقلة بشــأن اخلادمــة لكونهــا موقوفــة بإصالحيــة الدمــام‬\n\n                                                                                       ‫‪152‬‬\n\f      ‫قســم النســاء) وألقــي القبــض عليهمــا ومت إحالتهمــا إلــى مستشــفى‬\n      ‫القطيــف للكشــف عليهــا ولــم تــرد النتيجــة حتــى تاريخــه وباالطــاع‬\n      ‫علــى هاتفــي كل مــن املدعــى عليــه واخلادمــة تبــن ورود اتصــال بينهمــا‬\n      ‫ومبعاينــة املوقــع لوحظــت آثــار دمــاء وآثــار كســر جهــاز رســيفر مثبــت‬\n      ‫باجلــدار والــذي يدعــي املبلــغ بأنــه قــد ارتطــم رأس املدعــى عليــه بــه عنــد‬\n      ‫محاولتــه الهــرب وباســتجواب املدعــى عليــه أقــر أنــه يف يــوم اخلميــس‬\n      ‫املوافــق ‪1433/11/25‬ه ـ وعنــد قرابــة الســاعة العاشــرة مســاء خرجــت‬\n      ‫اخلادمــة مــن املنــزل لرمــي القمامــة فشــاهدها وكان يعمــل يف بوفيــه‬\n      ‫يف ذات العمــارة التــي تســكن بهــا اخلادمــة وأعطاهــا رقــم هاتفــه يف‬\n      ‫ورقــه فعــادت للدخــول للمنــزل ثــم خرجــت وأعطتــه رقــم هاتفهــا ثــم‬\n      ‫عــادت للدخــول للمنــزل مــرة أخــرى وبعــد ذلــك حصــل بينهمــا اتصــاالت‬\n      ‫هاتفيــة وطلبــت منــه احلضــور للمنــزل وعنــد حضــوره للمنــزل اتصــل علــى‬\n      ‫اخلادمــة وفتحــت لــه بــاب احلــوش اخللفــي للشــقة ثــم أدخلتــه وذهبــت بــه‬\n      ‫إلــى غرفتهــا اخلاصــة ثــم مكنتــه مــن نفســها وفعــل بهــا فاحشــة الزنــا‬\n      ‫وبعــد ذلــك دخــل صاحــب املنــزل واجتــه إلــى غرفــة اخلادمــة ووجدهــا‬\n      ‫عاريــة و شــاهده وبيــده فانيلتــه فأمســك بــه هــو وشــقيقه بعــد محاولتــه‬\n      ‫الهــرب وقــد أســفر التحقيــق عــن توجيه االتهــام للمدعى عليــه بانتهاكه‬\n      ‫حرمــة املنــزل وفعــل فاحشــة الزنــا باخلادمــة وبالبحــث عمــا إذا كان لــه‬\n      ‫ســوابق لــم تــرد حتــى تاريخــه وحيــث أن مــا أقــدم عليــه املذكــور وهــو‬\n      ‫بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرعا لــذا‬\n      ‫أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه باالتــي‪ :‬أوالً‪ :‬بحــد الزنــا‬\n      ‫غيــر احملصــن لقــاء قيامــه فعــل فاحشــة الزنــا ‪ -‬ثاني ـاً‪ :‬بعقوبــة تعزيريــة‬\n      ‫لقــاء انتهاكــه حلرمــة املنــزل ‪ -‬هــذا مــا ادعــى بــه وبعرضــه علــى املدعــى‬\n\n\n‫‪153‬‬\n\f‫ا مــا ذكــره املدعــي العــام يف دعــواه‬        ‫عليــه وبســؤاله عنــه أجــاب قائ ـ ً‬\n‫ضــدي مــن فعــل فاحشــة الزنــا باخلادمــة يف املنــزل الــذي تســكن فيــه‬\n‫وانتهاكــي حلرمتــه صحيــح هــذا مــا أجــاب بــه وبســؤاله عــن كيفيــة‬\n‫ا لقــد أوجلــت مقدمــة ذكــري يف‬         ‫فعلــه وهــل أولــج آلتــه فيهــا أجــاب قائـ ً‬\n‫دبرهــا مــن اخللــف وغيبتــه فيــه هــذا مــا أجــاب بــه وجــرى تكــرار الســؤال‬\n‫عليــه أربعـ ًا وأجــاب مبــا أجــاب بــه وبســؤاله عــن إحصانــه مــن عدمــه بــأن‬\n‫ا إنــه لــم يســبق لــي النــكاح هــذا مــا‬   ‫هــل ســبق لــه النــكاح أجــاب قائـ ً‬\n‫أجــاب بــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى‬\n‫عليــه بفعلــه الفاحشــة يف اخلادمــة بإيالجــه حلشــفة آلتــه يف دبرهــا وألنــه‬\n‫أقــر بــه أربع ـ ًا وإلقــراره بانتهــاك حرمــة املنــزل ولتحقــق شــروط وجــوب‬\n‫ا‬ ‫حــد الزنــا وهــي عنــد األصحــاب رحمهــم اهلل أن يطــأ يف الفــرج قب ـ ً‬\n‫كان أو دبــر ًا وأقــل مــا يطــأ بــه أن يغيــب حشــفته يف فــرج وأن تنتفــي‬\n‫الشــبهة وثبــوت الزنــا بشــهادة أو بإقــرار أربعـ ًا يف مجلــس أو مجالــس مــن‬\n‫بالــغ عاقــل يصــرح بذكــر حقيقــة الــوطء وحلديــث عبــادة يف صحيــح‬\n‫مســلم أن النبــي صلــى اهلل عليــه وســلم قــال (خــذوا عنــي خــذوا عنــي‬\n‫ال البكــر بالبكــر جلــد مائــة وتغريــب عــام‬          ‫قــد جعــل اهلل لهــن ســبي ً‬\n‫والثيــب بالثيــب جلــد مائــة والرجــم) لــذا وجلميــع مــا تقــدم فقــد ثبــت لــدي‬\n‫فعــل املدعــى عليــه لفاحشــة الزنــا يف دبــر أجنبيــة عنــه بإيــاج حشــفته‬\n‫وتغييبهــا فيــه وهــو غيــر محصــن وانتهاكــه حلرمــة املنــزل وقــررت أو ًال‬\n‫جلــد املدعــى عليــه مائــة جلــدة دفعــة واحــدة علنـ ًا وتغريبــه مــدة عــام حــد ًا‬\n‫للزنا ‪ -‬ثانياً‪ :‬ســجنه مدة ثمانية أشــهر يحتســب منها مدة إيقافه بســبب‬\n‫هــذه القضيــة وجلــده تســعني جلــدة النتهاكــه حرمــة املنــزل مفرقــة علــى‬\n‫دفعتــن كل دفعــة عــدد خمســة وأربعــن جلــدة بــن كل دفعــة وأخــرى‬\n\n\n                                                                                            ‫‪154‬‬\n\f      ‫مــدة أســبوعني مــع مراعــاة التفريــق بــن جلــد احلــد والتعزيــر‪ ،‬ومبا ذكر‬\n      ‫حكمــت وأوصيــت بإبعــاده مــن البــاد بعــد تنفيــذ العقوبة وبعد اســتيفاء‬\n      ‫مالــه ومــا عليــه مــن حقــوق وبعــرض احلكــم علــى الطرفــن اعتــرض‬\n      ‫عليــه املدعــي العــام وطلــب اســتئنافه دون تقــدمي الئحــة اعتراضيــة وقنــع‬\n      ‫بــه املدعــى عليــه وســيتم بعــث كامــل املعاملــة حملكمــة االســتئناف‬\n      ‫لتدقيــق احلكــم حســب املتبــع وللبيــان حــرر يف ‪1434/1/7‬ه ـ وصلــى‬\n                     ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n      ‫احلمــدهلل وحــده وبعــد لقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بالدمــام بكتــاب فضيلــة رئيســها رقــم ‪ 34181780‬يف ‪1434/2/17‬ه ـ‬\n      ‫املقيــدة يف هــذه احملكمــة ‪ 34434704‬يف ‪1434/2/20‬ه ـ واحملالــة‬\n      ‫مــن فضيلــة الرئيــس وبرفقهــا إعــام احلكــم الصــادر منــي برقــم ‪ .....‬يف‬\n      ‫‪1434/1/7‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة‬\n      ‫الثانيــة رقــم ‪ .....‬يف ‪1434/2/2‬ه ـ ونصــه بعــد املقدمــة وبدراســة القــرار‬\n      ‫وصــورة ضبطــه واوراق املعاملــة قررنــا املصادقــة علــى احلكــم واهلل‬\n      ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n      ‫‪1434/2/2‬ه ـ قاضــي اســتئناف ‪...‬ختمــه وتوقيعــه قاضي اســتئناف م‪...‬غ‬\n      ‫ختمــه وتوقيعــه رئيــس الدائــرة ‪ ...‬ختمــه وتوقيعــه أ‪.‬ه ـ وللبيــان حــرر يف‬\n      ‫‪1434/2/23‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبه‬\n                                                                          ‫أجمعــن‪....‬‬\n\n\n\n\n‫‪155‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":151,"source_page_end":155,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"93f4d32e466bcd6b9c972a267a5455e12dd28e7ef7c39a99b0a8245c229aadb6","normalized_text_hash":"1e6359383f9695afedb809d883c7be9390fa961b20b77ef91b1e3bee9c48a38c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p151-345654"},{"id":"f4137d4f-2e63-5833-aeb1-67d020bd61e3","document_type":"judgment","category":"judicial","subcategory":"general","title":"زنا -زنا احملصن -قبول الرجوع عن االعتراف يف احلدود -احلدود تدرأ بالشبهات -عدم قبول الرجوع عن االعتراف يف التعزيرات - ثبوت -تعزير بالسجن واجللد والتشهير .","document_number":"33268227","case_number":"3367474","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام كل من","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/05/25","year":"1434","subject":"زنا -زنا احملصن -قبول الرجوع عن االعتراف يف احلدود -احلدود تدرأ بالشبهات -عدم قبول الرجوع عن االعتراف يف التعزيرات - ثبوت -تعزير بالسجن واجللد والتشهير .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33268227 :‬تاريخه‪1433/05/25 :‬هـ‬\n                      ‫رقم الدعوى‪3367474 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 343602‬تاريخه‪1434/1/5 :‬هـ‬\n\n\n ‫زنــا ‪ -‬زنــا احملصــن ‪ -‬قبــول الرجــوع عــن االعتــراف يف احلــدود ‪ -‬احلــدود‬\n ‫تــدرأ بالشــبهات ‪ -‬عــدم قبــول الرجــوع عــن االعتــراف يف التعزيــرات ‪-‬‬\n                           ‫ثبــوت ‪ -‬تعزيــر بالســجن واجللــد والتشــهير ‪.‬‬\n\n\n\n\n ‫‪( .1‬قبــول الرجــوع عــن اإلقــرار يف احلــدود وهو مذهــب جمهور الفقهاء)‬\n                            ‫(كشاف القناع ‪ ،61/14‬الشرح الكبير ‪.)207/26‬‬\n                      ‫ـبه ِة ال ُي َ‬\n ‫قبـ ُـل فيهــا الرجــوع‬         ‫ـدرأ بالشـ َ‬\n                                          ‫إن حقــوق اهلل تعالــى التــي ال ُتـ َ‬‫‪َّ .2‬‬\n ‫ـبه ِة‬      ‫عــن اإلقــرار بــا ِخــاف‪ ،‬والتعازيـ ُـر مــن احلقــوق التــي ال ُتـ َ‬\n    ‫ـدرأ بالشـ َ‬\n ‫قبــل فيــه الرجــوع عــن اإلقــرار‪( .‬املغنــي ‪ ،95/5‬حاشــية ابــن عابدين‬  ‫فــا ُي َ‬\n                                                                            ‫‪. )60/4‬‬\n\n\n\n ‫إدعــى املدعــي العــام علــى املدعــى عليــه بقيامــه بارتــكاب فاحشــة الزنــا‬\n ‫وهــو محصــن‪ ،‬يطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد زنــا‬\n ‫احملصــن‪ .‬حيــث إن شــرطة الدمــام تلقــت بالغ ـ ًا مــن املنــاوب مبجمــع‬\n ‫الدمــام الطبــي عــن إحضــار امــرأة ســقطت يــوم األربعــاء املوافــق‬\n ‫‪1431/7/25‬ه ـ مــن نافــذة الشــقة التــي تســكن بهــا بالــدور الثالــث‬\n ‫بأحــد العمائــر الواقعــة يف حــي ‪ ...................‬بالدمــام وباالنتقــال‬\n\n                                                                                        ‫‪156‬‬\n\f      ‫الفــوري أتضــح بــأن املــرأة تدعــى‪ ......../‬وجــد بهــا إصابــات بليغــة ويف‬\n      ‫حالــة إغمــاء ومنومــة بالعنايــة املركــزة وقــد تعــذر اســتجوابها‪ .‬وبســماع‬\n      ‫أقــوال والــد الفتــاة ووالدتهــا ذكــرا أن ســبب وفاتهــا هــو زوجهــا املدعــى‬\n      ‫ـأن لــه عالقــة ســابقة بزوجتــه ‪...‬‬\n                                         ‫عليــه‪ .‬وباســتجواب املدعــى عليــه أقــر بـ ّ‬\n      ‫قبــل الــزواج بهــا حيــث زنــى بهــا وهــو محصــن أكثــر مــن مــرة ‪ -‬أنكــر‬\n      ‫املدعــى عليــه فعــل فاحشــة الزنــا وإمنــا هــي زوجتــه تــزوج بهــا بواليــة‬\n      ‫والدهــا ولكــن العقــد رســميا مت بعــد ســنة ثــم ولــدت بولــد بعــد العقــد‬\n      ‫بثالثــة أيــام واعترافــه بأنــه فعــل بهــا الزنــا لظنــه أن العقــد ال يصــح إال‬\n      ‫ـاء علــى مــا تقــدم حكمــت احملكمــة بــرد‬       ‫بعــد تســجيله رســمي ًا ‪ -‬بنـ ً‬\n      ‫دعــوى املدعــي العــام بإقامــة حــد الزانــي احملصــن علــى املدعــى عليــه‬\n      ‫ودرء احلــد عنــه وتتوجــه عليــه التهمــة القويــة يف ذلــك‪ .‬وتعزيــر املدعــى‬\n      ‫عليــه بالســجن ملــدة خمــس ســنوات تبــدأ مــن تاريــخ القبــض عليــه وجلــده‬\n      ‫خمســمائة جلــدة علــى دفعــات متســاوية كل دفعــة خمســون جلــدة وبــن‬\n      ‫كل دفعــة وأخــرى عشــرة أيــام‪ ،‬قــرر الطرفــان عــدم القناعــة وطلبــا‬\n              ‫االســتئناف بالئحــة ‪ُ ،‬صــدر احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــد وبعــد لدينــا‬\n      ‫نحــن قضــاة احملكمــة العامــة بالدمــام كل مــن‪ ... :‬و‪....‬و‪ ....‬القائــم بعمل‬\n      ‫املكتــب القضائــي العاشــر فتحــت اجللســة متام الســاعة الثامنــة والنصف‬\n      ‫ـاء علــى املعاملــة احملالــة مــن‬\n                                       ‫صباحــا مــن يــوم االثنــن ‪1433/2/8‬ه ـ بنـ ً‬\n      ‫فضيلــة الرئيــس برقــم ‪ .....‬واملقيــدة لــدى احملكمــة برقــم ‪ ....‬وتاريــخ‬\n      ‫‪1433/1 /25‬ه ـ وبهــا حضــر املدعــي العــام وا َّدعــى علــى احلاضــر معــه‬\n‫‪157‬‬\n\f‫ا يف دعــواه‬ ‫‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬قائ ـ ً‬\n‫عليــه ‪ :‬لقــد تلقــت شــرطة الدمــام بالغ ـ ًا مــن املنــاوب مبجمــع الدمــام‬\n‫الطبــي عــن إحضــار امــرأة ســقطت يــوم األربعــاء املوافــق ‪1431/7/25‬هـ‬\n‫مــن نافــذة الشــقة التــي تســكن بهــا بالــدور الثالــث بأحــد العمائــر‬\n‫الواقعــة يف حــي ‪...................‬بالدمــام وباالنتقــال الفــوري أتضــح بــأن‬\n‫املــرأة تدعــى‪22 .../‬ســنة ســعودية اجلنســية وجــد بهــا إصابــات بليغــة ويف‬\n‫حالــة إغمــاء و منومــة بالعنايــة املركــزة وقــد تعــذر اســتجوابها‪ .‬وبســماع‬\n‫أقــوال والــد الفتــاة ووالدتهــا ذكــرا أن ســبب وفاتهــا هــو زوجهــا املدعــى‬\n‫عليــه‪ .‬وباســتجواب املدعــى عليــه أنكــر التهمــة املنســوبة إليــه وقــال‬\n‫بأنــه متــزوج مــن ‪ ...‬منــذ ســنة وكانــت تقيــم عنــد أهلهــا ألنــه متــزوج‬\n‫مــن ثانيــة وال يســتطيع فتــح شــقة أخــرى وكان يزورهــا يف بيــت أهلهــا‬\n‫بحضــرة أمهــا ولــم تــأت شــقته إال قبــل احلادثــة بأربعــة أيــام‪ .‬وبإعــادة‬\n‫أن لــه عالقــة ســابقة بزوجتــه قبــل الــزواج بهــا حيــث زنــى‬\n                                                                ‫اســتجوابه أقــر ّ‬\n‫أن بينــه وبــن أهــل زوجتــه ‪...‬‬\n                                ‫بهــا وهــو محصــن أكثــر مــن مــرة ؛ وذكــر ّ‬\n‫أن‬\n ‫مشــاكل عديــدة بســبب تســترهم علــى ابنتهــم يف تنقالتهــا ؛ وأضــاف ّ‬\n‫لديــه شــكوك بنســبة ابنــه مــن ‪ ...‬إليــه ؛ كونــه متــزوج قبــل ‪ ...‬بخمــس‬\n‫ســنوات ومــع ذلــك لــم ينجــب ؛ كمــا أقــر أ ّنــه كان متغيب ـ ًا عــن العمــل‬\n‫وقــت وقــوع احلــادث (حفظــت الدعــوى بشــأن قضيــة القتــل لعــدم كفايــة‬\n‫األدلــة) وقــد انتهــى التحقيــق إلــى اتهــام املدعــى عليــه ‪ ...‬بارتــكاب‬\n‫فاحشــة الزنــا وهــو محصــن‪ ،‬وحيــث إن مــا أقــدم عليــه املذكــور فعــل‬\n‫محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n‫بحــد زنــا احملصــن‪ .‬وبســؤال املدعــى عليــه عــن الدعــوى أجــاب قائ ـاً‪:‬‬\n‫أطلــب إمهالــي جلســة أخــرى للجــواب عــن الدعــوى ويف جلســة أخــرى‬\n\n\n                                                                                     ‫‪158‬‬\n\f      ‫مبشــاركة فضيلــة القاضــي ‪ ...‬حضــر املدعــي العــام واملدعــى عليــه ويف‬\n      ‫هــذه اجللســة جــرى ســؤال املدعــى عليــه عــن الدعــوى فأجــاب قائـاً‪ :‬مــا‬\n      ‫أن زوجتي ‪ ...‬عقدت‬       ‫ذكــره املدعــي العــام يف دعــواه كلــه صحيح وذلــك َّ‬\n      ‫عليهــا بتاريــخ ‪1430/1/6‬ه ـ مبوجــب عقــد النــكاح الصــادر مــن هــذه‬\n      ‫احملكمــة برقــم ‪ ......‬يف ‪1430/1/6‬ه ـ وكانــت ثمــة عالقــة بينــي وبينها‬\n      ‫قبــل التقـ ُّـدم خلطبتهــا حيــث كانــت بيننــا مهاتفــات كل يومــن تقريب ـ ًا‬\n      ‫وأهاتفهــا ملــا يقــرب مــن ســاعة والــذي حصــل أنــه بعــد هــذه العالقــة‬\n      ‫ذهبــت إلــى بيــت والدهــا يف شــهر محــرم مــن عــام ‪1429‬ه ـ مــع مجموعــة‬\n      ‫مــن أهلــي وأحلحـ ُـت عليــه فقــال لــي‪« :‬زوجتــك إياهــا خــاص مــا عنــدي‬\n      ‫مانــع» وســلمت لــه حينهــا ثالثــة آالف ريــال وبعدها أصبحــت آتي إليها يف‬\n      ‫بيــت والدهــا وأخــرج معهــا وجامعتهــا أكثــر مــن مــرة وحملــت منــي وبعــد‬\n      ‫ســنة تقريب ـ ًا عقــدت عليهــا رســمي ًا عــن طريــق املــأذون الشــرعي وكان‬\n      ‫ذلــك بتاريــخ ‪1430/1/6‬ه ـ ثــم ولــدت ابنــي ‪ ..‬بعــد ثالثــة أيــام تقريب ـ ًا‬\n      ‫مــن العقــد الرســمي‪ .‬هــذا مــا حصــل‪ .‬فاعتــرايف لــدى هيئــة التحقيــق‬\n      ‫بأنــي فعلــت الفاحشــة بهــا أكثــر مــن مــرة صحيــح ولكــن هــذا لظنــي‬\n      ‫أن العقــد ال يتــم إال بعــد حضــور املــأذون الشــرعي وبعــد عقــدي عليهــا‬\n      ‫رســمي ًا ســكنت معــي يف شــقة‪ ،‬ثــم يف يــوم األربعــاء ‪1431/7/25‬ه ـ‬\n      ‫حصلــت واقعــة ســقوطها مــن الشــقة إلــى الــدور األرضــي ممــا أدى إلــى‬\n      ‫وفاتهــا علــى نحــو التفاصيــل التــي أوردهــا املدعــي العــام يف دعــواه لــذا‬\n      ‫فــا يســتحق املدعــي العــام علــى دعــواه شــيئ ًا وال ســبيل لــه علـ َّـي‪ .‬هــذه‬\n      ‫إجابتــي‪ .‬وبعــد ســماع الدعــوى واإلجابــة قــال املدعــي العــام الصحيــح مــا‬\n      ‫ـدي البينــة علــى ذلــك وهــي‬‫ذكرتــه وال صحــة ملــا ذكــره املدعــى عليــه ولـ َّ‬\n      ‫مــا يف أوراق املعاملــة‪ .‬بعدهــا جــرى االطــاع علــى اللفــة رقــم (‪ )218‬وقــد‬\n\n\n‫‪159‬‬\n\f‫تضمــن محضــر إعــادة اســتجواب مــن قبــل دائــرة التحقيــق يف قضايــا‬\n‫النفــس بهيئــة التحقيــق واالدعــاء العــام وقــد تضمــن مــا نصــه‪ « :‬بصفتــي‬\n‫أنــا احملقــق ‪ ....‬محقــق أول بدائــرة التحقيــق يف قضايــا النفــس يف يــوم‬\n                                                            ‫األربعــاء ‪1432/3/13‬ه ـ‬\n‫مت إحضــار املتهــم ‪ ....‬وبإعــادة اســتجوابه بشــأن طبيعــة العالقــة بينه وبني‬\n‫زوجتــه ‪ ...‬قبــل العقــد عليهــا أقـ َّـر بأنــه اختلــى بهــا مــرة واحــدة يف بدايــة‬\n‫تعرفــه عليهــا يف مجمــع ‪...................‬بكورنيــش الدمــام حيــث كان‬\n‫يتمشــى برفقتهــا‪ ،‬وأقــر أنــه قــام بتقبيــل ومفاخــذة ‪ ...‬قبــل زواجــه منهــا‪.‬‬\n‫اهــ‪ .‬توقيــع املتهــم ‪ ....‬كاتــب الضبــط‪ .... .‬احملقــق أول ‪ ....‬احملقــق ‪.....‬اهــ‪.‬‬\n‫وبعرضــه علــى املدعــى عليــه قــال‪ :‬هــذا احملضــر قــد وقعــت عليــه ومــا‬\n‫تضمنــه كلــه صحيــح عــدا أننــي فاخذتهــا وكانــت هــذه احلادثــة قبــل‬\n‫نحــو مــن ثمــان ســنوات‪.‬اهـ‪ .‬كمــا جــرى االطــاع علــى صــورة مــن وثيقــة‬\n‫عقــد الــزواج امل ـ ُ َـشار إلــى رقمــه وتاريخــه يف جــواب املدعــى عليــه كمــا‬\n‫يف اللفــة رقــم (‪ )10‬مــن الطــرد ‪.‬اهــ‪ .‬كمــا جــرى االطــاع علــى التحقيــق‬\n‫مــع املدعــى عليــه املعــد مــن قبــل هيئــة التحقيــق واالدعــاء العــام املرفــق‬\n‫باملعاملــة لفــة رقــم (‪ )109‬املعــد يف يــوم اخلميــس ‪1431/9/30‬ه ـ وقــد‬\n‫تضمــن مــا نصــه‪« :‬س‪ :‬متــى تزوجــت ‪ ...‬؟ ج‪ :‬منــذ ســنة تقريبـاً‪ .‬س‪ :‬وهــل‬\n‫كنــت علــى وفــاق معهــا ؟ ج‪ :‬حدثــت عالقــة بينــي وبينهــا قبــل الــزواج‬\n‫وتقدمــت لهــا ولكــن أهلهــا رفضــوا ومــن ثــم تزوجــت بأخــرى‪ ،‬وظلــت‬\n‫عالقتــي معهــا حيــث كانــت تزورنــي يف املنــزل‪ ،‬ومــن ثــم تزوجتهــا كــي‬\n‫أصحــح عالقتــي بهــا‪ .‬س‪ :‬كيــف تزوجتهــا رغــم أن أهلهــا رفضــوا ســابق ًا‬\n‫؟ ج‪ :‬ألنهــا حملــت وخوف ـ ًا مــن اهلل ذهبــت وتقدمــت لهــا وتزوجتها‪.‬اهــ‪.‬‬\n‫وبعرضــه عليــه قــال‪ :‬هــذا الــكالم قــد بصمــت عليــه بطوعــي واختيــاري‬\n\n\n                                                                                           ‫‪160‬‬\n\f      ‫ولكــن الصحيــح مــا ذكرتــه يف جوابي‪.‬اهــ‪ .‬كمــا جــرى االطــاع علــى‬\n      ‫التحقيــق مــع املدعــى عليــه مــن قبــل هيئــة التحقيــق واالدعــاء العــام‬\n      ‫املرفــق باملعاملــة لفــة رقــم (‪ )198‬وقــد تضمــن مــا نصــه‪ « :‬س‪ :‬أنــت متهــم‬\n      ‫بالزنــى ؟ ج‪ :‬غيــر صحيــح‪ .‬س‪ :‬متــى تعرفــت علــى املدعــوة ‪ ...‬؟ ج‪ :‬قبــل‬\n      ‫ثمــان ســنوات‪ .‬س‪ :‬كيــف تعرفــت عليهــا ؟ ج‪ :‬قبــل ثمــان ســنوات تقريبـ ًا‬\n      ‫ال أذكــر بالضبــط‪ .‬س‪ :‬هــل حصــل بينكمــا أي معاشــرة جنســية قبــل‬\n      ‫عقــد الــزواج ؟ ج‪ :‬ال‪ .‬س‪ :‬كيــف حــدث حملهــا إذن‪ .‬ج‪ :‬ال أعلــم لكونــي‬\n      ‫أشــك أنــي عقيــم واحتمــال أن يكــون احلمــل مــن غيــري‪ .‬س‪ :‬ملــاذا هــذا‬\n      ‫الشــك ؟ ج‪ :‬ألنــي متــزوج مــن زوجتــي األولــى ‪ ...‬منــذ خمــس ســنوات ولــم‬\n      ‫يحصــل بيننــا حمــل وزوجتــي األولــى قامــت بالكشــف الطبــي علــى‬\n      ‫نفســها وكانــت ســليمة وطبيعيــة وأمــا أنــا فلــم أكشــف حتــى اآلن‪.‬اهــ‪.‬‬\n      ‫وبعرضــه عليــه قــال‪ :‬هــذا الــكالم قــد بصمــت عليــه بطوعــي واختيــاري‬\n      ‫ولكــن الصحيــح مــا ذكرتــه يف جوابــي ســابقاً‪.‬اهـ‪ .‬ويف جلســة أخــرى‬\n      ‫حضــر املدعــي العــام واملدعــى عليــه ويف هــذه اجللســة قــال املدعــي العــام‬\n      ‫لــدي زيــادة بينــة علــى مــا ذكــرت وهــي محضــر االســتجواب مــع املدعــى‬\n      ‫عليــه املرفــق مــع طــرد املعاملــة لفــة رقــم (‪ )250‬أطلــب االطــاع عليه‪.‬ا‪.‬هــ‪.‬‬\n      ‫بعدهــا جــرى االطــاع عليــه وقــد تضمــن التحقيــق مــع املدعــى عليــه مــن‬\n      ‫قبــل احملقــق ‪ ....‬محقــق أول بدائــرة التحقيــق يف قضايــا النفــس يــوم‬\n      ‫الثالثــاء ‪1432/5/15‬ه ـ وممــا جــاء يف التحقيــق مــا نصــه‪ « :‬س وضــح‬\n      ‫كيــف تعرفــت علــى زوجتــك ‪ ...‬قبــل الــزواج بهــا؟ ج‪ :‬قبــل ســبع ســنوات‬\n      ‫تقريبــا ذهبــت إلــى مطعــم ‪...................‬وهنــاك تعرفــت عليهــا‪ ،‬وحدثــت‬\n      ‫عالقــة معهــا عــن طريــق الهاتــف بعــد ذلــك حصــل أول لقــاء بينــي وإياهــا‬\n      ‫بســيارتي اخلاصــة‪ ،‬ثــم قابلتهــا مبنــزل عمهــا بحــي ‪...................‬بجــوار‬\n\n\n‫‪161‬‬\n\f‫املدرســة ‪ ...‬الســاعة الثالثــة صباحــا‪ ،‬حيــث اختليــت بهــا داخــل غرفــة‬\n‫بنــت عمهــا وهنــاك حصــل بيننــا مقدمــات جنســية مــن تقبيــل ومفاخــذة‪،‬‬\n‫وبعــد ذلــك بســنة تقريبــا تقدمــت خلطبتهــا‪ ،‬إال أنــه لــم تتــم اخلطبــة بســبب‬\n‫خالف بني أمها ووالدها وقالوا لي بنرد عليك بعد أسبوعني‪ ،‬وما ردوا‬\n‫علــي‪ ،‬فتزوجــت مــن (‪ )...‬واســتمرت عالقتــي ب‪ ...‬رغــم عــدم ارتباطــي‬\n‫بهــا شــرعا‪ ،‬ثــم بعــد ذلــك حصــل حمــل بســبب معاشــرتي اجلنســية ل‪،...‬‬\n‫فاتصلــت والدتهــا علــي وطلبــت أن أعيــد الكــرة يف خطبــة ابنتهــا وأن‬\n‫أنتهــز هــذه الفرصــة‪ ،‬فتقدمــت مــرة أخــرى للــزواج بهــا فوافــق والدهــا‬\n‫وعنــد كتابــة العقــد طلــب والدهــا ثمانــن ألــف مقــدم وكذلــك مؤخــر‬\n‫الأذكــر مقــداره بالتحديــد‪ ،‬فلــم تتــم اخلطبــة‪ ،‬وبعــد عــدة محــاوالت‬\n‫وافــق والدهــا مبهــر وقــدره ثمانيــة عشــرة ألــف ريــال مقــدم‪ ،‬ومؤخــر‬\n‫خمســة عشــر ألفــا‪ ،‬ودفعــت ثالثــة آالف فقــط ومت عقــد النــكاح‪ ،‬ولــم‬\n‫أمتكــن مــن إســكانها إال قبــل ســقوطها بأربعــة أيــام فقــط‪ .‬س‪ ... :‬؟ ج‪:‬‬\n‫كثيــر‪ ،‬ال أذكــر بالتحديــد‪ .‬س‪ :‬هــل مارســت مــع زوجتــك ‪ ...‬املمارســة‬\n‫اجلنســية التــي ذكرتهــا ســابق ًا قبــل الــزواج منهــا كمــا يجامــع الرجــل‬\n                                                                   ‫زوجتــه ؟ ج‪ :‬نعــم‪.‬‬\n‫س‪ :‬حتــى بعــد الــزواج مــن األولــى ؟ ج‪ :‬نعــم‪ .‬س‪ :‬هــل لديــك أقــوال‬\n‫أخــرى ؟ ج‪ :‬أنــا لــم أفعــل هــذه األفعــال مــع ‪ ...‬إال أنــي أحبهــا وكنــت‬\n‫راغب ـ ًا الــزواج بهــا‪ ،‬وقــد تبــت إلــى اهلل وقمــت بتصحيــح عالقتــي بهــا‬\n‫وتزوجتهــا زواج ـ ًا شــرعياً‪ .‬احملقــق أول‪ .... .‬التوقيــع‪ .‬املتهــم ‪ ....‬التوقيــع‪.‬‬\n‫اهــ‪ .‬وبعرضــه عليــه‪ :‬قــال هــذا لقــد وقعــت علــى هــذا التحقيــق بطوعــي‬\n‫واختيــاري ولكــن الصحيــح مــا ذكرتــه ســابقاً‪.‬اهـ‪ .‬ويف جلســة أخــرى‬\n‫حضــر املدعــي العــام واملدعــى عليــه‪ .‬ويف هــذه اجللســة قــال املدعــي العام‪:‬‬\n\n\n                                                                                         ‫‪162‬‬\n\f      ‫ليــس لــدي زيــادة بينــة ســوى مــا ذكرت‪.‬اهــ‪ .‬ثــم جــرى ســؤال املدعــى‬\n      ‫عليــه هــل لديــك بينــة علــى مــا دفعــت بــه مــن كــون مجامعتــك مــع املــرأة‬\n      ‫‪ ...‬إمنــا كان بعــد أن قــال لــك والدهــا‪ « :‬زوجتــك إياهــا خــاص «‪ .‬فقــال‪:‬‬\n      ‫أطلــب إحضــار والــد الفتاة‪.‬اهــ‪ .‬ويف جلســة أخــرى حضــر املدعــي العــام‬\n      ‫واملدعــى عليــه كمــا حضــر يف هــذه اجللســة والــد الفتــاة املجنــي عليهــا‬\n      ‫وهــو ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬وبســؤاله‬\n      ‫عمــا َدفـ َـع بــه املدعــى عليــه أجــاب قائ ـاً‪ :‬مــا ذكــره املدعــى عليــه مــن‬\n      ‫العقــد غيــر الرســمي هــذا غيــر صحيــح فلــم يتــم العقــد علــى ابنتــي علــى‬\n      ‫النحــو الــذي وصفــه والــذي حصــل أننــي حــن علمــت بحمــل البنــت قمــت‬\n      ‫بالتعميــم وعمــل بالغــات عليــه لــدى اجلهــات الرســمية فحضــر إلينــا‬\n      ‫قبــل والدتهــا بثالثــة أيــام ومت إجــراء عقــد النــكاح ثــم ولــدت بعــد ذلــك‬\n      ‫فأنــا لــم أجلــس معــه قبــل العقــد الرســمي املــؤرخ يف ‪1430/1/6‬ه ـ أبــد ًا‬\n      ‫ولــم يســلم لــي قبــل ذلــك ثالثــة آالف ريــال ولــم أقــل لــه زوجتــك إياهــا‬\n      ‫خــاص هــذا مــا حصل‪.‬اهــ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه قــال‪:‬‬\n      ‫إن والــد الفتــاة بينــي وبينــه عــداوة لكونــه يتهمنــي بقتــل ابنتــه وليــس‬\n      ‫ـاء علــى مــا تقـ َّـدم مــن دعــوى‬ ‫ـدي بينــة علــى مــا دفعــت بــه ســابقاً‪.‬اهـ‪ .‬فبنـ ً‬\n                                                                                              ‫لـ َّ‬\n      ‫املدعــي العــام املتضمنــة اعتــراف املدعــى عليــه بفعــل فاحشــة الزنــا وهــو‬\n      ‫محصــن ويطلــب إقامــة حــد الزانــي احملصــن عليــه وجــواب املدعــى عليــه‬\n      ‫املتضمــن مصادقتــه علــى االعتــراف بفعــل الفاحشــة ودفــع بأ َّنــه مت العقد‬\n      ‫مــع املــرأة ‪ ...‬بأركانــه وشــروطه ولكنــه لــم يوثــق رســمي ًا عــن طريــق‬\n      ‫املــأذون وأنــه كان يظــن أن العقــد ال يتــم إال باملــأذون ومبــا أ َّنــه لــم يقــدم‬\n      ‫وأن والــد الفتــاة أنكــر ذلــك ومــن ناحيــة‬      ‫بينــة علــى هــذا الدفــع الســيما َّ‬\n      ‫ـإن هــذا الدفــع يعتريــه عــدة أمــور جتعلــه ضعيف ـ ًا وهــي اآلتــي‪:‬‬        ‫أخــرى فـ َّ‬\n\n‫‪163‬‬\n\f‫أوالً‪ /‬أن املدعــى عليــه اعتــرف أنــه فعــل الفاحشــة‪ ،‬وهــذا املصطلــح ال‬\n‫يخفــى معنــاه علــى مــا كان يف بــاد اإلســام‪ ،‬ومــا َف َّســره يف جوابــه‬\n‫مــن ظنــه أن العقــد ال يتــم إال رســمي ًا لــم يتعــرض لــه البتــة يف جميــع‬\n‫ملفــات التحقيــق‪ .‬ثاني ـاً‪ /‬مــا ذكــره املدعــى عليــه يف اللفــة رقــم (‪)109‬‬\n‫مــن أن زواجــه باملــرأة ‪ ...‬كان بســبب حملهــا منــه وخوفـ ًا مــن اهلل ذهبــت‬\n‫وتقــدم خلطبتهــا‪ .‬ثالث ـاً‪ /‬مــن الواضــح جــد ًا اضطــراب املدعــى عليــه يف‬\n‫اجلــواب حيــث ذكــر يف اللفــة رقــم (‪ )198‬أنــه يشــك يف نســبة ابنــه الــذي‬\n‫حملتــه ‪...‬؛ لكونــه يشــك يف كونــه عقيم ـاً‪ .‬بينمــا ذكــر يف إقــراره‬\n‫علــى اللفــة رقــم (‪ )250‬أنــه اختلــى ب‪ ...‬قبــل التقــدم خلطبتهــا وحصــل‬\n‫بينهمــا معاشــرة جنســية مــرات كثيــرة وصـ َّـرح أنــه مــارس معهــا مــا‬\n‫ميــارس الرجــل مــع زوجتــه فحملــت منــه ثــم بعــد ذلــك تقــدم خلطبتهــا وأنــه‬\n‫يتــوب إلــى اهلل ممــا فعــل‪ .‬وجميــع هــذه اإلقــرارات والتحقيقــات صــا َدق‬\n‫عليهــا املدعــى عليــه يف جلســات الترافــع‪ .‬فتلــك إقــرارات صريحــة بفعــل‬\n‫فاحشــة الزنــا ومبــا أ ّنــه رجــع عــن إقــراره والرجــوع مقبــول ويــدرأ عنهمــا‬\n‫احلـ َّـد عنــد جمهــور الفقهــاء (كشــاف القنــاع ‪ ،61/14‬الشــرح الكبيــر‬\n‫ـاء علــى مــا تضمنــه إقــرار املدعــى عليــه بطوعــه واختيــاره‬        ‫‪ .)207/26‬وبنـ ً‬\n‫مــن قيامــه بتقبيــل ومفاخــذة املــرأة ‪ ...‬قبــل العقــد عليهــا كمــا يف اللفــة‬\n‫أن هــذا يعتبــر‬ ‫رقــم (‪ )218‬ومصادقتــه علــى ذلــك عــدا املفاخــذة ومبــا َّ‬\n‫رجوع ـ ًا عــن اإلقــرار وقــد قـ َّـرر أهــل العلــم َأ َّن حقــوق اهلل تعالــى التــي ال‬\n‫قبــلُ فيهــا الرجــوع عــن اإلقــرار بــا خِ ــاف‪ ،‬والتعازيـ ُـر‬   ‫ـدرأ بالشــب َه ِة ال ُي َ‬\n                                                                                           ‫ُتـ َ‬\n‫قبــل فيــه الرجــوع عــن اإلقــرار‪.‬‬ ‫ـدرأ بالشــب َه ِة فــا ُي َ‬\n                                                              ‫مــن احلقــوق التــي ال ُتـ َ‬\n‫أن فاحشــة الزنــا مــن‬  ‫(املغنــي ‪ ،95/5‬حاشــية ابــن عابديــن ‪ .)60/4‬ومبــا َّ‬\n‫الســبع املوبقــات ومؤذنــة بخطــر جســيم علــى املجتمعــات املســلمة وفيهــا‬\n\n\n                                                                                                   ‫‪164‬‬\n\f      ‫إهــدار ملقصــد حفــظ العــرض والنســل التــي جــاء الشــرع بهمــا‪ ،‬الســيما‬\n      ‫ـتمرت عالقتــه باملــرأة ‪ ...‬بعــد زواجــه‬\n                                              ‫وأن املدعــى عليــه محصــن حيــث اسـ َّ‬    ‫َّ‬\n      ‫مــن امرأتــه ‪ .....‬وهــذا يســتدعي زيــادة يف تعزيــره وردعــه لذلــك كلــه‬\n                                                                       ‫فقــد قررنــا اآلتــي‪:‬‬\n      ‫أوالً‪ /‬رددنــا دعــوى املدعــي العــام بإقامــة حــد الزانــي احملصــن علــى‬\n      ‫املدعــى عليــه ودرأنــاه عنــه وتتوجــه إليــه التهمــة القويــة يف ذلــك‪ .‬ثاني ـاً‪/‬‬\n      ‫ثبــت لدينــا إدانــة املدعــى عليــه مبفاخــذة وتقبيــل امــرأة ال متــت لــه بصلــة‬\n      ‫شــرعية وإقامــة عالقــة محرمــة معهــا‪ .‬ثالثـاً‪ /‬قررنــا تعزيــر املدعــى عليــه‬\n      ‫بالســجن ملــدة خمــس ســنوات تبــدأ مــن تاريــخ القبــض عليــه وجلــده‬\n      ‫خمســمائة جلــدة علــى دفعــات متســاوية كل دفعــة خمســون جلــدة وبــن‬\n      ‫كل دفعــة وأخــرى عشــرة أيــام علــى أن تنفــذ ثــاث دفعــات مــن دفعــات‬\n      ‫اجللــد أمــام جامــع ‪ ......‬بالدمــام مقابــل البوابــة الشــمالية‪ .‬وبذلــك كلــه‬\n      ‫حكمنــا وبعــرض احلكــم علــى املدعــى العــام واملدعــى عليــه قــررا عــدم‬\n      ‫القناعــة وطلبــا رفــع كافــة أوراق املعاملــة إلــى محكمــة االســتئناف‬\n      ‫بالئحــة اعتراضيــة فأفهــم كل واحــد منهمــا باملراجعــة خــال عشــرة‬\n      ‫أيــام الســتالم نســخة احلكــم لتقــدمي االعتــراض عليــه يف مــدة أقصاهــا‬\n      ‫ثالثــون يومـ ًا فــإذا مضــت ولــم يعتــرض ســقط حقــه يف االعتراض وســيتم‬\n      ‫رفــع كافــة أوراق املعاملــة إلــى محكمــة االســتئناف بــدون الئحــة‬\n      ‫وكانــت ســاعة النطــق باحلكــم متــام الســاعة احلاديــة عشــرة والنصــف‬\n      ‫ظهــرا‪ .‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                          ‫وصحبــه وســلم‪ .‬حــرر يف ‪1433/5/24‬هــ‪.‬‬\n      ‫احلمــدهلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n      ‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n\n\n‫‪165‬‬\n\f‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام‬\n‫برقــم ‪ 33/176200‬وتاريــخ ‪1433/9/24‬ه ـ واملقيــدة لــدى احملكمــة‬\n‫برقــم ‪/33/1776962‬خ‪ 1‬وتاريــخ ‪1433/10/10‬ه ـ املرفــق بهــا القــرار‬\n‫الشــرعي ذو الرقــم ‪ .......‬والتاريــخ ‪1433/5/25‬ه ـ الصــادر مــن أصحــاب‬\n‫الفضيلــة القضــاة باحملكمــة الشــيخ ‪.... /‬والشــيخ ‪.... /‬والشــيخ ‪.... /‬‬\n‫اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد ‪ .... .... /‬يف قضيــة فاحشــة زنــا‬\n‫وقــد تضمــن القــرار حكــم أصحــاب الفضيلــة مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n            ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/1/5‬هـ ـ ـ ـ ‪.‬‬\n\n\n\n\n                                                                                ‫‪166‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":156,"source_page_end":166,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6ccfc0f5fd9a3e9d0c017410dde206c9904a8309523949f20bcdb771625ebcdd","normalized_text_hash":"463ea6477d8f00ee0e56f09f821143ad1382846380e74b1b33284ece5e665a10","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p156-33268227"},{"id":"fbc89115-ca0a-5976-b285-9573cb9bfacf","document_type":"judgment","category":"judicial","subcategory":"general","title":"زنا -زنا غير احملصن -حد الزنا لغير محصن -تغييب فتاة عن منزل أهلها -الرجوع عن احلكم بحد زنا غير احملصن -الرجوع عن إقرارها بالزنا -احلدود تدرأ بالشبهات -تعزير بالسجن واجللد.","document_number":"34248330","case_number":"3494397","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبنطقة مكة املكرمة اإلطاع على املعاملة الواردة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/21","year":"1434","subject":"زنا -زنا غير احملصن -حد الزنا لغير محصن -تغييب فتاة عن منزل أهلها -الرجوع عن احلكم بحد زنا غير احملصن -الرجوع عن إقرارها بالزنا -احلدود تدرأ بالشبهات -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34248330 :‬تاريخه ‪1434/6/21‬هـ‬\n                         ‫رقم الدعوى‪3494397 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34380448‬تاريخه‪1434/12/18 :‬هـ‬\n\n\n      ‫زنــا ‪ -‬زنــا غيــر احملصــن‪ -‬حــد الزنــا لغيــر محصــن‪ -‬تغييــب فتــاة عــن‬\n      ‫منــزل أهلهــا‪ -‬الرجــوع عــن احلكــم بحــد زنــا غيــر احملصــن ‪ -‬الرجوع عن‬\n       ‫إقرارهــا بالزنــا ‪ -‬احلــدود تــدرأ بالشــبهات ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫‪ .1‬قــول اهلل تعالــى (الزانيــة والزانــي فاجلــدوا كل واحــدٍ منهمــا مائــة‬\n                                                                    ‫جلــدة) [النــور‪.]2 :‬‬\n      ‫‪ .2‬قولــه صلــى اهلل عليــه وســلم ‪« :‬ادرؤوا احلــدود بالشــبهات مــا‬\n                                                                         ‫ا ســتطعتم » ‪.‬‬\n      ‫ـاء‬\n      ‫‪ .3‬مــا جــاء يف كتــاب عمــر رضــي اهلل عنــه‪« :‬وال مينعنــك قضـ ٌ‬\n               ‫قضيتــه باألمــس أن تراجــع فيــه نفســك فــإن احلــق قــدمي»‪.‬‬\n      ‫‪ .4‬القاعــدة الفقهيــة‪ :‬إقــرار اإلنســان علــى نفســه مقبــول‪ .‬ينظــر‪ :‬الــدر‬\n                                                                  ‫املنثــور للســيوطي ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليهما(امــرأة ورجــل غيــر محصنــن)‬\n      ‫بإقامــة عالقــة محرمــة و فعــل فاحشــة الزنــا وقيــام املدعــى عليهــا‬\n      ‫بالتغيــب عــن منــزل ذويهــا وقيــام املدعــى عليــه بالتســبب يف تغيبهــا‬\n      ‫وإيوائهــا طيلــة فتــرة تغيبهــا‪ ،‬واالعتــداء عليهــا بالضــرب وذلــك بعدمــا مت‬\n\n‫‪167‬‬\n\f‫ـاغ مــن شــقيق املدعــى عليهــا املتضمــن‬‫القبــض علــى املدعــى عليــه إثــر بـ ٍ‬\n‫تغيــب شــقيقته عــن املنــزل وعودتهــا إليــه برفقــة املدعــى عليــه الثانــي‪،‬‬\n‫وصــدر بحقهــا التقريــر الطبــي املتضمــن وجــود كدمــة بالوجــه و جتمــع‬\n‫دمــوي حــول العــن اليســرى ومــدة الشــفاء ســبعة أيــام وطلــب املدعــي‬\n‫العــام احلكــم عليهمــا بحــد زنــا غيــر احملصــن و احلكــم عليهمــا بعقوبــة‬\n‫تعزيريــة لقــاء عالقتهمــا احملرمــة ببعضهمــا‪ ،‬وتغيــب املدعــى عليهــا عــن‬\n‫ذويهــا وتســبب األول يف ذلــك‪ ،‬بعــرض دعــوى املدعــي العــام علــى املدعــى‬\n‫عليهمــا صادقــا عليهــا جملــة وتفصيــا‪ ،‬بنــاء علــى مــا تقــدم حكمــت‬\n‫احملكمــة بإقامــة حــد زنــا غيــر احملصــن علــى املدعــى عليــه بجلــده مائــة‬\n‫جلــدة دفعــة واحــدة وتغريــب عــام وتعزيــره لقــاء تغييبــه للفتــاة بجلــده‬\n‫ســتني جلــدة مفرقــة علــى ثــاث دفعــات‪ ،‬إقامــة حــد زنــا غيــر احملصــن‬\n‫علــى املدعــى عليهــا وجلدهــا مائــة جلــدة دفعــة واحــدة وتغريبهــا عــام‪،‬‬\n‫وتعزيرهــا لقــاء عالقتهــا احملرمــة والتغيــب عــن منــزل ذويهــا بجلدهــا‬\n‫ســبعني جلــدة مفرقــة علــى دفعتــن‪ ،‬بعــرض احلكــم علــى املدعــى‬\n‫عليــه قــرر القناعــة باحلكــم كمــا قــرر املدعــي العــام عــدم االعتــراض‬\n‫وقــررت املدعــى عليهــا االعتــراض وقدمــت املدعــى عليهــا الئحتهــا‬\n‫االعتراضيــة‪ ،‬ورجعــت فيهــا عــن إقرارهــا وذكــرت أن فعــل الفاحشــة‬\n‫كان باإلكــراه‪ -‬وألن احلــدود تــدرأ بالشــبهات مت الرجــوع عــن احلكــم‬\n‫علــى املدعــى عليهــا ســابق ًا بحــد الزنــا ومت احلكــم بتعزيرها لقــاء خلوتها‬\n‫الغيــر شــرعيه وعالقتهــا بأجنبــي ال ميــت لهــا بصلــة بســجنها مــدة شــهرين‬\n‫وجلدهــا تســعني جلــدة مفرقــة علــى ثــاث دفعــات وبعــرض ذلــك علــى‬\n‫املدعــى عليهــا قــررت قناعتهــا باحلكــم وبعرضــه علــى املدعــي العــام‬\n‫قــرر االعتــراض بالئحــة وبعــد رفــع احلكــم حملكمــة االســتئناف متــت‬\n\n\n                                                                                     ‫‪168‬‬\n\f                                                                        ‫املصادقــة عليــه‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنا ‪...‬القاضي يف احملكمة اجلزائية مبكة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة مبكــة املكرمــة برقــم ‪ 3494397‬وتاريــخ ‪ 1434/02/26‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34486512‬وتاريــخ ‪1434/02/26‬ه ـ ففــي‬\n      ‫يــوم االثنــن املوافــق ‪ 1434/03/16‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 15‬‬\n      ‫وفيهــا حضــر املدعــي العــام ‪ ...‬وادعــى علــى احلاضــر معــه ‪......‬نيجيريــة‬\n      ‫ا يف دعــواه عليهمــا‬ ‫اجلنســية إقامــة رقــم ‪...‬و‪...‬بالســجل املدنــي رقــم ‪...‬قائـ ً‬\n      ‫حيــث أنــه بتاريــخ ‪1434/1/22‬ه ـ مت القبــض علــى املدعــى عليــه الثانــي‬\n      ‫مــن قبــل الدوريــات األمنيــة علــى أثــر تلقيهــم بــاغ مــن املقيــم ‪.../‬شــقيق‬\n      ‫املدعــى عليهــا يتضمــن تغيــب شــقيقته املدعــى عليهــا عــن املنــزل بتاريــخ‬\n      ‫‪1434/1/18‬ه ـ وعودتهــا إليهــم يف تاريــخ ‪1434/1/21‬ه ـ برفقة املدعى‬\n      ‫عليــه التــي ال ميــت لهــا بصلــة أو قرابــة وقــد صــدر بحقهــا التقريــر الطبــي‬\n      ‫رقم (‪ ).....‬بتاريخ ‪1434/1/21‬هـ املتضمن وجود كدمة بالوجه وجتمع‬\n      ‫دمــوي حــول العــن اليســرى مــدة الشــفاء ســبعة أيــام وباســتجواب املدعــى‬\n      ‫عليــه أقــر بإقامــة عالقــة مــع املدعــى عليهــا منــذ ســنة وأقــر باصطحابهــا‬\n      ‫إلــى منزلــه يف محافظــة جــدة و ممارســة فعــل فاحشــة الزنــا مــع املدعــى‬\n      ‫عليهــا أكثــر مــن مــرة كمــا أقــر بضــرب املدعــى عليهــا وإعادتهــا إلــى‬\n      ‫مكــة كونــه الحــظ أنهــا تعانــي مــن حــاالت مــس وباســتجواب املدعــى‬\n      ‫عليهــا ‪... /‬أقــرت بعالقتهــا باملدعــى عليــه واالتصــال به هاتفي ًا والتنســيق‬\n      ‫معــه للذهــاب إلــى محافظــة جــدة مبنزلــه و ممارســة فعــل فاحشــة الزنــا‬\n\n‫‪169‬‬\n\f‫برضــا منهــا لوعــده لهــا بالــزواج كمــا ذكــرت أن املدعــى عليــه قــام‬\n‫بضربهــا أثــر معاناتهــا مــن حــاالت املــس وقــد انتهــى التحقيــق إلــى توجيــه‬\n‫االتهــام للمدعــى عليهمــا ‪ ...‬و ‪ ...‬بإقامــة عالقــة محرمــة و فعــل فاحشــة‬\n‫الزنــا وقيــام املدعــى عليهــا بالتغيــب عــن منــزل ذويهــا وقيــام املدعــى عليــه‬\n‫بالتسبب يف تغيبها وإيوائها طيلة فترة تغيبها واالعتداء عليها بالضرب‪.‬‬\n‫وذلــك لألدلــة والقرائــن التاليــة‪ -1:‬مــا جــاء يف أقــوال املدعــى عليــه ص‬\n‫(‪ )2-1‬لفــة (‪ - 2 )10‬مــا جــاء يف أقــوال املدعــى عليهــا ص(‪ )4 - 3‬لفــة‬\n‫(‪ -3 - )10‬محضــر القبــض املنــوه عنــه واملرفــق لفــة (‪ )2‬وحيــث أن مــا‬\n‫قــام بــه املدعــى عليهمــا وهمــا بكامــل أهليتهمــا الشــرعية فعــل محــرم‬\n‫ومعاقــب عليــه شــرع ًا ‪ -‬لــذا أطلــب إثبــات مــا أســند إليهمــا واحلكــم‬\n‫عليهمــا بحــد الزنــا غيــر احملصــن واحلكــم عليهمــا بعقوبــة تعزيريــة لقاء‬\n‫عالقتهمــا احملرمــة ببعضهمــا وتغيــب املدعــى عليهــا عــن ذويهــا وتســبب‬\n‫األول يف ذلــك علمــا بــأن احلــق اخلــاص اليــزال قائم ـ ًا وبســؤال املدعــى‬\n‫عليــه عــن دعــوى املدعــي العــام أجــاب مــا ذكــره املدعــي العــام يف دعــواه‬\n‫ا هــذه إجابتــي فبنــاء علــى مــا تقــدم‬  ‫أعــاه صحيــح كلــه جملــة وتفصيـ ً‬\n‫مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه ومبــا أن إقــرار اإلنســان‬\n‫علــى نفســه مقبــول والــدر املنثــور للســيوطي ‪ 126/2‬ولقــول اهلل تعالــى‬\n‫(الزانيــة والزانــي فاجلــدوا كل واحــدٍ منهمــا مائــة جلــدة) اآليــة ســورة‬\n‫النــور لــذا وجلميــع مــا تقــدم فقــد تقــرر لــي مــا يلــي أوالً‪ :‬ثبــت لــدي إدانــة‬\n‫املدعــى عليــه مبــا أســند إليــه مــن دعــوى املدعــي العــام بإقامــة عالقــة‬\n‫محرمــة وفعــل فاحشــة الزنــا وقيــام املدعــى عليــه بالتســبب يف تغيبهــا‬\n‫وإيوائهــا فتــرة تغيبهــا واالعتــداء عليهــا بالضــرب ‪ -‬ثاني ـاً‪ :‬قــررت جلــده‬\n‫مائــة جلــده دفعــة واحــدة وتغريــب عــام حــد الزنــا ‪ -‬ثالثـاً‪ :‬قــررت تعزيــره‬\n\n\n                                                                                             ‫‪170‬‬\n\f      ‫لقــاء تغيبــه للفتــاة بجلــده ســتون مفرقــة علــى ثــاث دفعــات كل دفعــة‬\n      ‫عشــرون جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام وأجلــت احلكــم‬\n      ‫علــى املدعــى عليهــا حلــن القبــض عليهــا ‪ -‬ومبــا ســبق كلــه حكمــت‬\n      ‫وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة باحلكــم كمــا قــرر‬\n      ‫املدعــي العــام عــدم االعتــراض وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n      ‫ســيدنا محمــد حــرر يف ‪1434/3/16‬ه ـ ويف هــذا اليــوم املوافــق األربعــاء‬\n      ‫املوافــق ‪1434/6/21‬ه ـ افتتحــت اجللســة الســاعة ‪ 10:00‬وفيهــا حضرت‬\n      ‫املدعــى عليهــا ‪...‬نيجيريــة اجلنســية مبوجــب إقامــة رقــم ‪ ...‬برفقــة معرفهــا‬\n      ‫الشــرعي أبوهــا ‪ ...‬نيجيــري اجلنســية مبوجــب إقامــة رقــم ‪...‬وبســؤال‬\n      ‫ا مــا ذكــره املدعــي‬   ‫املدعــى عليهــا عــن دعــوى املدعــي العــام أجــاب قائـ ً‬\n      ‫ا وأنــا نادمــة أشــد‬‫العــام يف دعــواه أعــاه صحيــح كلــه جملــة وتفصي ـ ً‬\n      ‫النــدم علــى مــا بــدر منــي هكــذا أجابــت فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة وإلقــرار املدعــى عليهــا ومبــا أن اإلقــرار حجــة شــرعية‬\n      ‫علــى املقــر ‪ -‬لــذا فقــد ثبــت لــدي إدانــة املدعــى عليهــا مبــا أســند إليهــا‬\n      ‫مــن دعــوى املدعــي العــام بإقامــة عالقــة محرمــة وفعــل فاحشــة الزنــا‬\n      ‫وقيــام املدعــى عليهــا بالتغيــب عــن منــزل ذويهــا وقــررت مايلــي أو ًال قررت‬\n      ‫إقامــة حــد الزنــا علــى املدعــى عليهــا وذلــك بجلدهــا مائــة جلــدة دفعــة‬\n      ‫واحــدة وتغريبهــا عــام ‪ ،‬ثاني ـاً‪ :‬قــررت تعزيرهــا لقــاء عالقتهــا احملرمــة‬\n      ‫التغيــب عــن منــزل ذويهــا بجلدهــا ســبعون جلــدة مفرقــة علــى دفعتــن‬\n      ‫كل دفعــة خمســة وثالثــون جلــدة بــن كل دفعــة وأخــرى أســبوع وملــا‬\n      ‫ســبق كلــه حكمــت وبعرضــه علــى املدعــى عليهــا قــررت االعتــراض‬\n      ‫بالئحــة وبعرضــه علــى املدعــي العــام قــرر قناعتــه باحلكــم كمــا جــرى‬\n      ‫تســليمها نســخة مــن احلكــم ‪ ....‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n\n\n‫‪171‬‬\n\f                                      ‫ســيدنا محمــد حــرر يف ‪1434/6/21‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء املوافــق ‪1434/7/5‬ه ـ‬\n‫افتحــت اجللســة الســاعة ‪ 12:30‬وفيهــا قدمــت املدعيــة ‪ ...‬الئحتهــا‬\n‫االعتراضيــة واملكونــة مــن صفحــة واحــدة واملتضمنــة مــا نصــه لقــد قــام‬\n‫املدعــى عليــه ‪ ...‬باالتصــال علــي وقــام بتهديــدي بنشــر الصــور املوجــودة‬\n‫علــى اجلهــاز الــذي قمــت بإعطائــه إيــاه لوضــع بعــض البرامــج اخلاصــة‬\n‫باجلهــاز وطلــب منــي احلضــور إليــه إذا أردت احلصــول علــى اجلهــاز دون أي‬\n‫مشــاكل فوصــف لــي املــكان فبــادرت بالذهــاب ألخــذ اجلهــاز وليــس‬\n‫لفعــل الفاحشــة كمــا ذكــر ومــا أن وصلــت إلــى هنــاك قــام بالقبــض‬\n‫علــى والتعــدي علــى بالضــرب حاولــت الدفــاع عــن نفســي قــدر املســتطاع‬\n‫إلــى أن فقــدت الوعــي والســيطرة وأتانــي وأنــا مكرهة ولــم أكن أعاني‬\n‫مــن مــس أو مــرض كمــا ذكــر وكان هــذا هــو ســبب تغيبــي عــن املنــزل‬\n‫واهلل علــى مــا أقــول شــهيد وجــرى ســؤال املدعــى عليهــا عــن مــا تدعيــه‬\n‫مــن اإلكــراه مــا صفتــه فأجابــت قائلــة بكالم عربي مفهــوم بأن املجني‬\n‫عليهــا ‪ :‬كانــت لــي معــه عالقــة محرمــة وقــد أعطيتــه جوالــي مــن أجــل‬\n‫يضــع برامــج بداخلــه ثــم طلبنــي للمجــيء إليــه لكــي آخــذ جوالــي وليــس‬\n‫لفعــل الفاحشــة وفجــأة ألزمنــي بشــدة بالدخــول للمنــزل وضربنــي ضربـ ًا‬\n‫شــديد ًا مبرح ـ ًا علــى وجهــي وخلــع مالبســي بالقــوة وفعــل بــي الفاحشــة‬\n‫وأنــا ال أشــعر مــا فعلــه مــن شــدة الضــرب هــذه إجابتــي فبنــاء علــى مــا‬\n‫تقــدم ممــا ذكــر أعــاه مــن الالئحــة االعتراضيــة ومــا ذكرتــه املدعيــة‬\n‫مــن اإلكــراه وملــا جــاء يف كتــاب عمــر رضــي اهلل عنــه وال مينعنــك قضاء‬\n‫قضيتــه باألمــس أن تراجــع فيــه نفســك فــإن احلــق قــدمي وملــا جــاء عــن‬\n‫النبــي صلــى اهلل عليــه وســلم (ادرؤوا احلــدود به بالشــبهات ما اســتطعتم)‬\n\n\n                                                                                    ‫‪172‬‬\n\f      ‫‪ -‬لــذا فقــد عدلــت عمــا حكمــت بــه مــن حــد الزنــا علــى املدعــى عليهــا‬\n      ‫إلــى تعزيرهــا لقــاء خلوتهــا الغيــر شــرعية وعالقتهــا بأجنبــي ال ميــت‬\n      ‫لهــا بصلــة بســجنها مــدة شــهرين محســوب ًا منهــا مــدة إيقافهــا يف هــذه‬\n      ‫القضيــة وجلدهــا تســعون جلــدة مفرقــة علــى ثــاث دفعــات كل دفعــة‬\n      ‫ثالثــون جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام لقــاء الشــبهة وجلميــع‬\n      ‫مــا ســبق كلــه حكمــت وبعرضــه علــى املدعــى عليهــا قــررت قناعتهــا‬\n      ‫باحلكــم وبعرضــه علــى املدعــي العــام قــرر االعتــراض بالئحــة كمــا‬\n      ‫جــرى تســليمه صــورة مــن احلكــم ‪ ..‬وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n                                     ‫علــى ســيدنا محمــد حــرر يف ‪1434/07/05‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى رســول اهلل ‪ ...‬وبعــد‪-:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الســابعة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة املســاعد برقــم‬\n      ‫‪ 341482100‬وتاريــخ ‪1434/11/25‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة الشــيخ‪ ... /‬القاضــي باحملكمــة اجلزائيــة مبكــة املكرمــة‬\n      ‫برقــم ‪ .......‬وتاريــخ ‪1434/6/21‬ه ـ املتضمــن دعــوى املدعــي العــام ضد‪...‬‬\n      ‫(العمــر‪ 24‬نيجيريــة اجلنســية) املتهمــة يف الهــروب والتغيــب والزنــى‪،‬‬\n      ‫احملكــوم فيــه مبــا دون بباطــن القــرار‪ ،‬وبدراســة القــرار وصورة ضبطه‬\n      ‫والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم بحــق املدعــى عليــه‬\n      ‫وكذلــك احلكــم الــذي صــدر بحــق املدعــى عليهــا ‪ .‬واهلل املوفــق وصلــى‬\n                               ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪173‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":167,"source_page_end":173,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c9842c07821fd93aa8a5d5ea6022fcdd9003893d010a040ba3aadd1976f7861a","normalized_text_hash":"1072091ae48ca95eb16abec43c587814b407d168a163675c9c20b0c7bfc6c6b8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p167-34248330"},{"id":"8ada2599-93da-5af1-874b-9446c9b394e1","document_type":"judgment","category":"judicial","subcategory":"general","title":"زنا -غير محصن -ابتزاز -تهديد بحيازة جوال يحتوي على صور عارية -جرائم معلوماتية -ابتزاز فتاة مبقابل مادي -إقامة حد الزاني غير محصن -تعزير للشبهة -تعزير بالسجن واجللد ومصادرة اجلوالن.","document_number":"33380550","case_number":"33407255","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/14","year":"1434","subject":"زنا -غير محصن -ابتزاز -تهديد بحيازة جوال يحتوي على صور عارية -جرائم معلوماتية -ابتزاز فتاة مبقابل مادي -إقامة حد الزاني غير محصن -تعزير للشبهة -تعزير بالسجن واجللد ومصادرة اجلوالن.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33380550‬تاريخه‪1433/8/14 :‬هـ‬\n                        ‫رقم الدعوى‪33407255 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34241768‬تاريخه‪1434/6/14 :‬هـ‬\n\n\n      ‫زنــا ‪ -‬غيــر محصــن ‪ -‬ابتــزاز ‪ -‬تهديــد بحيــازة جــوال يحتــوي علــى‬\n      ‫صــور عاريــة ‪ -‬جرائــم معلوماتيــة ‪ -‬ابتــزاز فتــاة مبقابــل مــادي ‪ -‬إقامــة‬\n      ‫حــد الزانــي غيــر محصــن ‪ -‬تعزيــر للشــبهة ‪ -‬تعزيــر بالســجن واجللــد‬\n                                                               ‫ومصــادرة اجلوالــن‪.‬‬\n\n\n\n      ‫‪ -1‬قــول اهلل تعالــى « الزانيــة والزانــي فاجلــدوا كل واحــد منهمــا مائــة‬\n                                                                            ‫جلدة»‬\n      ‫‪ -2‬قولــه صلــى اهلل عليــه وســلم « البكــر بالبكــر جلــد مائــة و تغريــب‬\n                                                                              ‫عــام»‬\n\n\n\n\n      ‫الئحــة الدعــوى العامــة ضــد املدعــى عليــه مســلم غيــر محصــن باتهامــه‬\n      ‫باالرتبــاط بعالقــة محرمــة مــع فتــاة وفعــل فاحشــة الزنــا برضاهــا‬\n      ‫وتهديدهــا وتهديــد والدتهــا بنشــر صورهــا وحيــازة جهــازي جــوال‬\n      ‫وذاكــرة إلكترونيــة حتتــوي علــى صــور عاريــة للفتــاة ورســائل تهديــد‬\n      ‫لهــا ولغيرهــا وطلــب املدعــي العــام إثبــات مــا اســند إليــه واحلكــم عليــه‬\n      ‫بحــد الزانــي غيــر احملصــن وتعزيــره ومصــادرة اجلوالــن والذاكــرة‬\n      ‫اإللكترونيــة املضبوطــة مــع إتالفهــا‪ ،‬مت القبــض علــى املدعــى عليــه‬\n\n‫‪181‬‬\n\f‫مــن قبــل هيئــة األمــر باملعــروف والنهــي عــن املنكــر إثــر شــكوى مــن‬\n‫امــرأة مفادهــا أن املدعــى عليــه علــى عالقــة بابنتهــا وأنــه اســتدرجها‬\n‫وفعــل بهــا الفاحشــة وأنــه حــاز صورهــا ويقــوم بتهديدهــا وتهديــد ابنتهــا‬\n‫ومت القبــض عليــه بعــد أن مت التنســيق مــع الفتــاة باإلتفــاق مــع املدعــى‬\n‫عليــه ولقائــه ليتــم القبــض عليــه باجلــرم املشــهود‪ ،‬مت عــرض الدعــوى‬\n‫علــى املدعــى عليــه فأجــاب بــأن مــا جــاء يف دعــوى املدعــي العــام صحيــح‬\n‫باســتثناء التهديــد بنشــر صــور الفتــاة وأضــاف املدعــى عليــه بــأن الفتــاة‬\n‫هــي التــي تطلــب التصويــر كمــا أنكــر قيامــه بتهديــد الفتــاة ووالدتهــا‪،‬‬\n‫عــدم وجــود بينــه موصلــة علــى تهديــد الفتــاة بنشــر صورهــا وفضحهــا‬\n‫واســتدراجها إال ماجــاء يف محضــر القبــض وأقوالــه التــي توجــه التهمــة‬\n‫للمدعــى عليــه‪ ،‬صــدر احلكــم بثبــوت إدانــة املدعــى عليــه بفعــل فاحشــة‬\n‫الزنــا وعــدم ثبــوت إدانتــه بتهديــد الفتــاة ونشــر صورهــا وفضحهــا‬\n‫وابتزازهــا‪ ،‬إقامــة حــد الزانــي غيــر احملصــن بجلــده مائــة جلــدة دفعــة‬\n‫واحــدة وتغريبــه عــن مدينــة الريــاض مــدة عــام وتكــون مســافة التغريــب‬\n‫عائــدة للجهــات املختصــة‪ ،‬تعزيــر لقــاء الشــبهة القويــة بتهديــد الفتــاة‬\n‫ونشــر صورهــا وهــي عاريــة بســجنه ســتة أشــهر وجلــده خمســن جلــدة‬\n‫دفعــة أخــرى ويفصــل بــن جلــد احلــد وجلــد التعزيــر عشــرة أيــام ومصادرة‬\n‫جهــازي اجلــوال وذاكــرة اجلــوال و إتالفهــا‪ ،‬مت تصديــق احلكــم مــن‬\n                                                        ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n\n                                                                                    ‫‪182‬‬\n\f      ‫اجلزائيــة بالريــاض برقــم ‪ 33407255‬وتاريــخ ‪1433/06/16‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331135542‬وتاريــخ ‪ 1433/06/16‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافق‪1433/06/24‬ه ـ افتتحــت اجللســة الســاعة ‪: 01‬‬\n      ‫‪12‬وفيهــا حضــر املدعــي العــام وادعــى علــى ‪ 27 ، ...... /‬ســنة ‪ ،‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬غيــر محصــن ‪ ،‬موقــوف‬\n      ‫بتاريــخ ‪1433/6/5‬ه ـ مبوجــب أمــر إحالــة ومتديــد توقيــف رقــم ه ـ‬\n      ‫ر‪ 63519/3/1‬وتاريــخ ‪1433/6/8‬ه ـ اســتنادا للمــادة (‪ )112‬مــن نظــام‬\n      ‫اإلجــراءات اجلزائيــة ‪ .‬قائــا يف دعــواه إنــه بتاريــخ ‪1433/6/5‬ه ـ قبــض‬\n      ‫علــى املذكــور مــن قبــل هيئــة األمــر باملعــروف والنهــي عــن املنكــر‪/‬‬\n      ‫مركــز هيئــة ‪ .....‬إثــر شــكوى مقدمــه مــن امــرأة مفادهــا قيــام‬\n      ‫املذكــور بربــط العالقــة احملرمــة بابنتهــا واســتدراجها والذهــاب بهــا‬\n      ‫إلــى شــقق مفروشــة وممارســة الفاحشــة معهــا وتهديدهــا بنشــر صورهــا‬\n      ‫والتــي حصــل عليهــا عــن طريــق تصويرهــا وذلــك بعــد رفــض زواجــه بهــا‬\n      ‫وأنــه اتصــل عليهــا وهددهــا بنشــر صــور ابنتهــا وفضحهــا وبالتنســيق‬\n      ‫مــع ابنتهــا جــرى االتفــاق مــع املذكــور للحضــور إليهــا عنــد إحــدى‬\n      ‫املشــاغل النســائية ألخذهــا عندهــا مت القبــض عليــه وضبــط معــه علــى‬\n      ‫جهــازي جــوال حتــت مرتبــة الســائق تبــن باالطــاع عليهــا أنهــا حتتــوي‬\n      ‫علــى مجموعــة صــور للفتــاة ورســائل بهــا تهديــد ورســالة تهديــد أخــرى‬\n      ‫لفتــاة أخــرى ورســائل غراميــة وأرقــام فتيــات كمــا مت ضبــط ذاكــرة‬\n      ‫ممــوري قــام املذكــور بإحضارهــا تبــن أنهــا حتتــوي علــى صــور عاريــة‬\n      ‫للفتــاة وصــور لعورتهــا وباالطــاع علــى التســجيل الصوتــي بــن املذكــور‬\n      ‫وبــن الفتــاة تبــن إقــراره باالتصــال علــى والدهــا لفضحهــا واالتصــال‬\n      ‫علــى والدتهــا وهددهــا بنشــر صورهــا عنــد اجليــران وأقــر بأنــه حصــل‬\n\n\n‫‪183‬‬\n\f‫علــى مبالــغ ماليــة مــن الفتــاة وأنــه فعــل بهــا الفاحشــة يف عــدة أماكــن‬\n‫‪ .‬بســماع أقــوال املذكــور واســتجوابه اعتــرف بربــط العالقــة احملرمــة‬\n‫بابنــة املشــتكية والذهــاب بهــا إلــى شــقق وفنــادق وفعــل الفاحشــة بهــا‬\n‫برضاهــا بإيــاج عــدة مــرات واعتــرف بتصويرهــا عــدة صــور وهــي‬\n‫عاريــة وأقــر بتهديدهــا بنشــر صورهــا وتهديــد والدتهــا بنشــر صــور‬\n‫ابنتهــا وذلــك بعــد رفضهــم تزويجهــا لــه وأقــر بحيــازة ماضبــط معــه‬\n‫مــن جهــازي جــوال وذاكــرة ممــوري ‪ .‬وأســفرت إجــراءات التحقيــق‬\n‫عــن اتهامــه بربــط العالقــة احملرمــة بفتــاة وفعــل فاحشــة الزنــا برضاهــا‬\n‫وتهديدهــا ووالدتهــا بنشــر صورهــا وحيــازة جهــازي جــوال وذاكــرة‬\n‫ممــوري حتتــوي علــى صــور عاريــة للفتــاة ورســائل تهديــد لهــا ولغيرهــا‬\n‫واملجــرم مبوجــب نظــام مكافحــة اجلرائــم املعلوماتيــة الصــادر باملرســوم‬\n                              ‫امللكــي رقــم (م‪ )17/‬وتاريــخ ‪1428/3/8‬هــ‪.‬‬\n‫وذلــك لألدلــة والقرائــن التاليــة‪.1 :‬اعترافــه املــدون علــى الصفحة (‪ )1‬من‬\n‫دفتــر التحقيــق (‪.2 )2‬محضــر القبــض املرفــق علــى اللفــة (‪.3 )7‬محضــر‬\n‫املشــاهدة املرفــق علــى اللفــة (‪ .4 )5-4‬محضــر االســتماع املرفــق علــى‬\n‫اللفــة (‪ . )6‬وببحــث ســوابقه اتضــح عــدم وجــود ســوابق حتــى تاريخــه ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا‬\n‫ونظام ـ ًا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد الزانــي غيــر‬\n‫احملصــن وتعزيــره ومعاقبتــه مبوجــب املــادة (‪ )6‬ومصــادرة جهــازي‬\n‫اجلوالــن وذاكــرة املمــوري املضبوطــة مــع إتالفهــا اســتنادا للمــادة (‪)13‬‬\n‫مــن النظــام املشــار إليــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                    ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/06/24‬ه ـ‬\n‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه ‪ - ....‬ســعودي بالهويــة‬\n\n\n                                                                                        ‫‪184‬‬\n\f      ‫رقــم(‪ )............‬اجــاب بقولــه ماجــاء يف دعــوى املدعــي العــام مــن ربــط‬\n      ‫العالقــة مــع أحــد الفتيــات وممارســة الزنــا معهــا وقيامــي بتصويرهــا‬\n      ‫وهــي غيــر عاريــة فهــذا صحيــح وقــد مارســت الزنــا معهــا برضاهــا‬\n      ‫بإيــاج كامــل حيــث قمــت بإيــاج ذكــري يف فرجهــا وانزلــت خــارج‬\n      ‫رحمهــا ومــا يتعلــق بالتصويــر فالفتــاة هــي التــي كانــت تطلــب منــي‬\n      ‫تصويرهــا وترســل لــي رســائل بصورهــا وهــي عاريــة بــدون مالبــس‪ .‬امــا‬\n      ‫مــا جــاء يف دعــوى املدعــي العــام مــن تهديــدي لهــا أو لوالدتهــا فهــذا غيــر‬\n      ‫صحيــح وكل مــا يف األمــر أنــي اتصلــت علــى والدتهــا وقلــت لهــا أنــا‬\n      ‫أنســان أرغــب الــزواج وابنتــك كلمــا أردت اخلطبــة تطلــب منــي إعــادة‬\n      ‫خطبتهــا مــن والدهــا فإمــا ان متســكني ابنتــك أو ســأكلم والدهــا‬\n      ‫ليتصــرف معهــا هــذا مــا قلتــه لهــا ولــم أهددهــا او أهــدد والدتهــا بنشــر‬\n      ‫صورهــا وال صحــة لوجــود رســائل تهديــد يف أجهــزة اجلــوال العائــدة لــي‬\n      ‫وكل مــا يف االمــر أن شــقيقة الفتــاة اخبرتنــي أنهــا تكلــم شــاب ًا آخــر‬\n      ‫فقمــت بارســال رســالة لهــا تتضمــن أنــي ال أرضــى بــان عيــال احلــرام‬\n      ‫يلعبــون فيــك‪ .‬ثــم جــرى ســؤال املدعــى عليــه عــن واقعــة الزنــا فاجــاب‬\n      ‫نعــم لقــد قمــت بفعــل فاحشــة الزنــا بالفتــاة وذلــك بايــاج ذكــري يف‬\n      ‫فرجهــا وقمــت باالنــزال خــارج الرحــم‪ .‬هكــذا اجــاب‪ .‬ورفعــت اجللســة‬\n      ‫للتأمــل‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر بتاريــخ‬\n                                                                       ‫‪1433/6/24‬هــ‪.‬‬\n      ‫ويف يــوم االثنــن ‪1433/7/7‬ه ـ افتتحــت اجللســة الثانية الســاعة العاشــرة‬\n      ‫والنصــف وفيهــا حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليــه وقد‬\n      ‫جــرى ســؤال املدعــى عليــه عــن واقعــة الزنــا فأجــاب قائــا لقــد فعلــت‬\n      ‫فاحشــة الزنــا بالفتــاة املذكــورة وذلــك بإيــاج ذكــري يف فرجهــا وقمــت‬\n\n\n‫‪185‬‬\n\f‫باإلنــزال خــارج الرحــم وكان ذلــك برضاهــا وجــرى ســؤاله مــره ثالثــة‬\n‫فاجــاب بنعــم لقــد فعلــت فاحشــة الزنــا بالفتــاة املذكــورة وذلــك بايــاج‬\n‫ذكــري يف فرجهــا وقمــت باالنــزال خــارج الرحــم وكان ذلــك برضاهــا‬\n‫ثــم جــرى ســؤاله مــرة رابعــة فاجــاب نعــم لقــد فعلــت فاحشــة الزنــا بالفتــاة‬\n‫املذكــورة وذلــك بإيــاج ذكــري يف فرجهــا وقمــت باالنــزال خــارج‬\n‫الرحــم وكان ذلــك برضاهــا هكــذا قــرر‪ .‬وبعــرض ذلــك علــى املدعــي‬\n‫العــام أجــاب بقولــه أطلــب الرجــوع للمعاملــة لالطــاع علــى مــا يثبــت‬\n‫قيــام املدعــى عليــه بتهديــد الفتــاة املذكــورة هكــذا أجــاب‪ .‬وبالرجــوع‬\n‫للمعاملــة وجــد فيهــا محضــر القبــض الصــادر مــن مركــز هيئــة األمــر‬\n‫باملعــروف والنهــي عــن املنكــر حــي ‪ ............‬بتاريــخ ‪1433/6/5‬ه ـ‬\n‫ويتضمــن تقــدم والــدة الفتــاة ملركــز الهيئــة بشــكوى ضــد املدعــى عليــه‬\n‫بأنــه يقــوم بتهديــد ابنتهــا إن لــم تخــرج معــه وســبق لــه أن أدخلها يف فنادق‬\n‫وشــقق مفروشــة وقــام بتصويرهــا وقــد هــدد الفتــاة إن لــم تخــرج معــه‬\n‫ســيقوم بنشــر الصــور وتضمــن احملضــر طلــب تســجيل أي مكاملــة يقــوم‬\n‫بهــا املدعــى عليــه عنــد اتصالــه بالفتــاة كمــا تضمــن احملضــر إســتدراج‬\n‫املدعــى عليــه عــن طريــق الفتــاة بالركــوب معــه مــن أحــد املشــاغل‬\n‫النســائية ومت القبــض عليــه وبعــد القبــض عليــه انهــار وطلــب الســتر وأن‬\n‫مــا ورد يف الشــكوى صحيــح جملــة وتفصيــا وأفــاد بوجــود ذاكــرة‬\n‫هاتــف يف منزلــه وقــام بإحضارهــا عــن طريــق والدتــه وتبــن ان الذاكــرة‬\n‫بهــا مجموعــة صــور للفتــاة املشــتكية وهــي عاريــة وشــبه عاريــة وصورها‬\n‫الشــخصية كمــا تبــن أن هاتفيــه احملمولــن يحتويــان علــى محادثــات‬\n‫ورسائل فيها صيغة التهديد أ هـ‪ .‬كما وجد يف املعاملة محضر استماع‬\n‫مكاملــات مســجلة صــادرة مــن املدعــى عليــه‪ ،‬األولــى تفيــد بانــه اتصــل‬\n\n\n                                                                                        ‫‪186‬‬\n\f      ‫علــى والدهــا ثمــان مــرات ولــم يــرد وذلــك لغــرض فضحهــا كمــا افــاد‬\n      ‫بانــه اتصــل علــى والدتهــا املشــتكية وهددهــا بنشــر صورهــا للجيــران‬\n      ‫وعلــى بــاب منزلهــا ويف وســائل اإلعــام وأقــر بأنــه كان يتحصــل علــى‬\n      ‫مبالــغ ماليــة مــن مكافئتهــا اجلامعيــة لغــرض عــدم نشــر صورهــا كمــا‬\n      ‫تضمــن احملضــر االطــاع علــى مراســات علــى برنامــج (الواتــس اب)‬\n      ‫وممــا قالــه واهلل لــو مــا تــرد علــي ال تلــوم اال نفســها _ لــو مــا تــردون‬\n      ‫بيصيــر فيكــم مصيبــة _ أ ه ـ ‪ .‬ومحضــر القبــض ومحضــر االســتماع‬\n      ‫موقــع عليهمــا مــن قبــل عضــوي هيئــة االمــر باملعــروف والنهــي عــن‬\n      ‫املنكــر ‪ ............‬و‪ .............‬وبعــرض مــا جــاء يف احملضريــن علــى املدعــى‬\n      ‫عليــه اجــاب بقولــه ال صحــة ملــا جــاء يف احملضريــن مــن قيامــي بتهديــد‬\n      ‫الفتــاة وابتزازهــا وتصويرهــا وهــي عاريــة وال صحــة ملــا جــاء يف احملضــر‬\n      ‫مــن القبــض علــي عنــد احــد املشــاغل النســائية وهــي برفقتــي هكــذا‬\n      ‫اجــاب‪ .‬وبعــرض ذلــك علــى املدعــي العــام اجــاب بقولــه اطلــب اعطائــي‬\n      ‫مهلــة إلحضــار شــاهدي احملضــر فأجيــب لطلبــه ورفعــت اجللســة الــى‬\n      ‫يــوم االثنــن ‪1433/7/14‬ه ـ إلحضــار البينــة وجــرى رفــع اجللســة الســاعة‬\n             ‫احلاديــة عشــر ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n      ‫ويف يــوم االثنــن ‪1433/7/14‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n      ‫العــام وحضــر حلضــوره املدعــى عليــه وبســؤال املدعــي العــام عــن البينــة‬\n      ‫أجــاب بقولــه لــم أمتكــن مــن إحضارهــا يف هــذه اجللســة وأطلــب مهلــة‬\n      ‫أخــرى إلحضارهــا فأجيــب لطلبــه ورفعــت اجللســة إلــى يــوم االثنــن‬\n           ‫‪1433/7/21‬ه ـ واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n      ‫ويف يــوم االثنــن ‪1433/7/28‬ه ـ أفتتحــت اجللســة وفيهــا حضــر املدعــي‬\n      ‫العــام وحضــر حلضــوره املدعــى عليــه الســجني وبســؤال املدعــي العــام عن‬\n\n\n‫‪187‬‬\n\f‫بينتــه أجــاب بقولــه لــم أمتكــن مــن إحضارهــا هكــذا أجــاب ثــم جــرى‬\n‫ســؤال املدعــى عليــه عــن اإلحصــان فأجــاب قائــا إننــي غيــر متــزوج‬\n‫ولــم يســبق لــي الــزواج مطلقــا وأنــا مــن ســكان مدينــة الريــاض هكــذا‬\n‫أجــاب فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي العــام وإجابــة املدعــى‬\n‫عليــه وحيــث أقــر املدعــى عليــه بقيامــه بفعــل فاحشــة الزنــا بالفتــاة‬\n‫املذكــورة يف الدعــوى وذلــك بإيــاج ذكــره يف فرجهــا وكــرر إقــراره‬\n‫بذلــك أربــع مــرات وحيــث أنكــر املدعــى عليــه قيامــه بتهديــد الفتــاة‬\n‫وابتزازهــا واســتدراجها وتهديدهــا بنشــر صورهــا وفضحهــا وحيــث إن‬\n‫مــا جــاء يف محضــر القبــض يــورث الشــبهة جتــاه ذلــك فعليــه فقــد تقــرر‬\n‫مــا يلــي ‪ :‬أوال ‪ :‬ثبــت لــدي قيــام املدعــى عليــه بفعــل فاحشــة الزنــا وذلــك‬\n‫بإيــاج ذكــره يف فــرح الفتــاة املذكــورة يف الدعــوى ولقولــه عــز وجــل ‪:‬‬\n‫( الزانيــة والزانــي فاجلــدوا كل واحــد منهمــا مائــة جلــدة) وقــول النبــي‬\n‫صلــى اهلل وعليــه وســلم (البكــر بالبكــر جلــد مائــة وتغريــب عــام )‬\n‫وإلقــرار املدعــى عليــه بأنــه غيــر محصــن فقــد حكمــت علــى املدعــى‬\n‫عليــه بحــد الزانــي الغيــر محصــن وذلــك بجلــده مائــة جلــدة دفعــة واحــدة‬\n‫وتغريبــه عــن مدينــة الريــاض ملــدة عــام علــى أن يكــون حتديــد مســافة‬\n‫التغريــب عائــد للجهــة املختصــة ‪ .‬ثانيــا ‪ :‬لــم يثبــت لــدي قيــام املدعــى‬\n‫عليــه بتهديــد الفتــاة بنشــر صورهــا وفضحهــا وابتزازهــا واســتدراجها‬\n‫إال إن مــا جــاء يف محضــر القبــض ويف أقوالــه مــا يــورث الشــبهة القويــة‬\n‫جتــاه ذلــك وقــررت تعزيــره لقــاء الشــبهة ولقــاء اعترافــه باحتــواء جهــازه‬\n‫اجلــوال لصــور الفتــاة وهــي عاريــة وذلــك بســجنه ســتة أشــهر مــن تاريــخ‬\n‫إيقافــه وجلــده خمســن جلــدة دفعــة واحــدة بينهــا وبــن اجللــد الــذي يف‬\n‫أوال عشــرة أيــام ‪ .‬ثالثــا ‪ :‬مصــادرة جهــازي اجلــوال املذكورين يف الدعوى‬\n\n\n                                                                                       ‫‪188‬‬\n\f      ‫وكــذا مصــادرة ذاكــرة اجلــوال وإتالفهــا‪ -‬وبجميــع ذلــك حكمــت‬\n      ‫وبعرضــه علــى املدعــي العــام قــرر االعتــراض مكتفيــا بالئحــة الدعــوى‬\n      ‫أمــا املدعــى عليــه فقــد قــرر القناعــة باحلكــم واهلل املوفــق وصلــى اهلل‬\n                           ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n      ‫ويف يــوم االربعــاء ‪1434/1/28‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n      ‫العــام وحضــر حلضــوره املدعــى عليــه ‪ _ ........‬ســعودي بالهويــة رقــم ‪.....‬‬\n      ‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم‬\n      ‫‪ 33479331‬يف ‪1433/12/27‬ه ـ ونــص احلاجــة منــه ‪ :‬وبدراســة القــرار‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة لوحــظ ان مــا حكــم بــه فضيلتــه مــن‬\n      ‫تعزيــر قليــل وال يتفــق مــع اجلــرم املنســوب للمدعــى عليــه يف الئحــة‬\n      ‫الدعــوى وألن هــذا الفعــل تغريــر بالفتيــات عــن طريــق الوعــد بالــزواج‬\n      ‫وإشــاعة الفاحشــة يف املجتمــع واإلعتــداء علــى العــرض واملتعــن تعزيــر‬\n      ‫املدعــى عليــه مبــا يحفــظ األعــراض ووقايــة املجتمــع مــن الفاحشــة‪.‬‬\n      ‫وبــاهلل التوفيــق ‪ .‬أ ه ـ ‪ .‬فعليــه ولوجاهــة مــا ذكــره أصحــاب الفضيلــة‬\n      ‫فقــد رجعــت عــن التعزيــر املثبــت يف الفقــرة الثانيــة مــن احلكــم وقــررت‬\n      ‫تعزيــره وذلــك بســجنه عشــرة اشــهر مــن تاريــخ إيقافــه وجلــد مائــة‬\n      ‫وخمســن جلــده مفرقــة علــى ثــاث دفعــات كل دفعــة خمســون جلــدة‬\n      ‫بــن كل دفعــة وأخــرى عشــرة أيــام وبــن هــذا اجللــد واجللــد الــذي يف‬\n      ‫أو ًال خمســة عشــر يومــا وبذلــك حكمــت ‪ .‬وبعرضــه علــى املدعــي العــام‬\n      ‫قــرر بأنــه ال زال معترضــا أمــا املدعــى عليــه فقــد قــرر القناعــة باحلكــم‬\n      ‫فأمــرت بإحلــاق ذلــك يف القــرار‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى‬\n                                                                        ‫نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده أطلــع قضــاة الدائــرة اجلزائيــة األولــى علــى املعاملــة‬\n\n\n‫‪189‬‬\n\f‫الــواردة مــن احملكمــة اجلزائيــة بالريــاض برقــم ‪ 34118392‬وتاريــخ‬\n‫‪1434/4/20‬ه ـ واملرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‪..... /‬‬\n‫برقــم ‪ ......‬وتاريــخ ‪1433/8/14‬ه ـ واخلــاص بدعــوى املدعــي العــام ضد‪/‬‬\n‫‪ ......‬وموضوعهــا قضيــة زنــا وتهديــد وبعــد التدقيــق يف إجابــة فضيلــة‬\n‫ناظــر القضيــة وفقــه اهلل علــى قــرار محكمــة االســتئناف الســابق تقــرر‬\n‫املصادقــة علــى احلكــم لعــدم موجــب املالحظــة مــع تنبيــه فضيلتــه إلــى‬\n‫تدويــن اســم املدعــي العــام وفقــا للمــادة ‪ 156‬مــن نظــام اإلجــراءات‬\n                     ‫اجلزائيــة وصلــى اهلل علــى نبينــا محمــد واهلل املوفــق‪.‬‬\n\n\n\n\n                                                                                   ‫‪190‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":181,"source_page_end":190,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f7f23dd9e36d8dbb6e1815753ab8affd20f9a10d6defa641bd7f21043f8af2a3","normalized_text_hash":"465640f7c0dd1e3923006a12cfc9e2faaba1f7c263b742a04f7104a3135bec50","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p181-33380550"}]$archive_payload$::jsonb AS data)
